import { ForProps } from "src/types/control";
import React, { useMemo } from "react";
import { ReactNode } from "react";
import Store from 'src/components/container/store';
import { JSONSchemaCustom } from "../schema";
import { executeJsCode, executeSandboxedCode } from "src/utils/function";

export const forPropsSchema: JSONSchemaCustom = {
    type: "object",
    properties: {
        "of":{
            "type":"string",
            "format":"nodeInput",
            "title":"绑定数组字段（array）"
        },
        "each":{
            "type":"string",
            "title":"数组对象",
            "default":"item"
        },
        "index":{
            "type":"string",
            "title":"数组下标",
            "default":"index"
        },
        "varName": {
            "type": "string",
            "title": "定义变量"
        },
        "varBody": {
            "type": "string",
            "title": "变量定义",
            "format": "js"
        },
        "children":{
            "type":"array"
        }
    }
}

export default ({ each, of, index, varName, varBody, children }: ForProps) => {

    const list: any[] = React.Children.toArray(children);
    if(!Array.isArray(of) || of.length === 0){
        return list.map((Element, j) => {
            if(!Element.props.contentData) return Element;
            const contentData: Store = Object.create(Element.props.contentData);
            contentData._arguments = {
                ...contentData._arguments,
                [each || "item"]: {},
                [index || "index"]: 0
            }
            if(varName && varBody){
                contentData._arguments[varName] = executeJsCode(varBody, contentData);
            }
            // console.log('contentData', contentData, varBody)
            
            Object.assign(contentData, contentData._arguments);
            return (
                <React.Fragment key={j}>
                    {React.cloneElement(Element, {
                        contentData
                    })}
                </React.Fragment>
            )
        });
    }
    // 编辑时只展示一个
    return of.slice(0,1).map((item, i) => {
        return list.map((Element, j) => {
            if(!Element.props.contentData) return Element;
            const contentData: Store = Object.create(Element.props.contentData);
            contentData._arguments = {
                ...contentData._arguments,
                [each || "item"]: item,
                [index || "index"]: i
            }
            if(varName && varBody){
                contentData._arguments[varName] = executeJsCode(varBody, contentData);
            }
            
            Object.assign(contentData, contentData._arguments);
            return (
                <React.Fragment key={j}>
                    {React.cloneElement(Element, {
                        contentData
                    })}
                </React.Fragment>
            )
        })
    })
}