import { useEffect, useMemo } from 'react';
import { JSONSchemaCustom } from 'src/components/schema';
import _ from 'lodash';
import { getRefSchema, schemaToFormItem } from 'src/utils/form';

interface RefSchemaProps {
    $ref?: string;
    schema?: JSONSchemaCustom;
    field?: string;
    renderFormItemList: any;
}

const RefSchema = (props: RefSchemaProps) => {

    const schema: JSONSchemaCustom = useMemo(() => {
        const [s, paths] = getRefSchema(props.$ref, props.schema);
        if(s){
            const objSchema = _.cloneDeep(s);
            objSchema.title = objSchema.title || paths.pop();
            objSchema.definitions = _.cloneDeep(props.schema.definitions)
            return objSchema
        }
        return null;
    }, [])

    const formList = useMemo(() => {
        if(!schema) return [];
        return schemaToFormItem(schema, props.field)
    },[schema])
    
    if(!formList.length) return null;

    return props.renderFormItemList(formList);
}


export default RefSchema;