/**
 * 接口参数类型定义
 */
export interface properItem {
    // 参数类型
    kind?: SyntaxKind | SyntaxKindS;
    // 全文带注释
    fullText?: string;
    // 类型文本
    text?: string;
    // 属性名称
    name?: string;
    // 是否必填
    required?: boolean;
    // 注释
    jsDocs?: jsDocProps[];
    // 类型
    flag?: TypeFlags;
    // 对象类型
    objFlag?: ObjectFlags;
    // 多个类型
    children?: Array<properItem>;
    // 对象类型属性
    properties?: properItem;
    // 返回类型 （函数参数）
    returnType?: properItem;
}

// 接口属性
export interface InterfaceItem {
    // 名称
    name: string;
    // 注释
    jsDocs?: jsDocProps[],
    children: properItem[]
}
/**
 * 定义由typescript 结构的输出出来的数据模型
 */
export interface TransformType {
    interfaces?: InterfaceItem[];
}