import { delayedFunction, getUuid } from "src/utils";
import { action, computed, observable, runInAction, toJS, makeObservable } from "mobx";
import { FunctionNodeDataProps, insertPosition } from "../../interface";
import { getBuilderItems, getDataBuilder, getTranslations } from "src/utils/builder";
import { builderItem } from "src/types/expression";
import config from "src/config";
import moduleStore from "src/store/moduleStore";
import PageStore from '../../BaseStore';
import _ from 'lodash';
import { SpecialItem } from "src/types/module";

interface Constructor {
    page: PageStore;
    id: string;
    props: any;
    key: string;
}

export default class Store {
    id: string;
    key: string;
    page: PageStore;
    source: string;
    // 插入在容器最外层
    portal = false;
    // dom 重绘
    isRepaint = false;

    // 如果是容器，插入位置在上侧还是下侧
    @observable isTop = false;
    @action
    setIsTop = (bool) => {
        this.isTop = bool;
    }

    // children 是否为functionNode 类型
    isFunctionNode?: boolean = false;
    funParams?: string[];

    // 是否包含动态数据 （原逻辑，现应无特殊意义）
    isDynamicData?: boolean = false;
    // propsKey
    @observable propsKey = getUuid('hash');
    @action
    updatePropsKey = () => {
        this.propsKey = getUuid('hash');
    }
    
    // 插入方式 true作为子集插入
    @observable mode = false;
    @action
    setMode = (bool) => {
        this.mode = bool;
    }

    /**
     * 根据 mode， 和 isTop 返回将要插入组件位置
     */
    @computed get position(){
        if(this.mode){
            return insertPosition.children;
        }
        return this.isTop? insertPosition.prev : insertPosition.next;
    }

    builders: builderItem[] = [];
    /**
     *  组件的初始值
     */
    @observable props: any = {
    }

    // 解析后多语言后的值
    @computed get propsData(): any{
        return getTranslations(this.page.contentData, _.cloneDeep(this.props));
    }

    getProps = () => {
        const contentData = this.page.contentData;
        let props = { key: this.propsKey, ...this.propsData}
        // 对引用的值进行解析
        props = getDataBuilder(props, this.builders, contentData)
        // 根据schema类型，对返回值进行修改
        props = moduleStore.getModuleProps(this.key, props, contentData);
        
        if(this.source === "custom"){
            props['data-u'] = this.id;
        }else {
            props[`data-v-${this.id}`] = "";
        }
        return props;
    }

    domProps: any = {};

     // 延迟更新 delayedFunction 优化渲染太频繁
    @action
    setProps = delayedFunction(action((data) => {
        this.builders = getBuilderItems(toJS(data), this.key);
        this.props = data || {};
        if(this.isRepaint) this.updatePropsKey(); // dom 重绘
        this.domProps = this.getProps();
        if(this.portal){
            const page = this.page;
            // portal 组件渲染在最外层
            page.setList([...page.list])
        }
    }), 300)

    constructor({ props, key, id, page }: Constructor){
        makeObservable(this);
        this.id = id;
        this.key = key;
        this.page = page;
        const element = moduleStore.elements.get(key);
        this.source = element.source;
        if(element.specialPaths && element.specialPaths.some((o) => {
            return Boolean(config.schema.sources[o.format]);
        })){
            // 存在动态数据
            this.isDynamicData = true;
        }
        const { properties = {} } = element.props || {}
        const { children = {} } = properties;
        if(children.format === "functionNode"){
            this.isFunctionNode = true;
        }
        if(children.functionType && children.functionType.arguments){
            this.funParams = children.functionType.arguments.map((o) => o.title);
        }
        const { extraInfo } = element;
        if(extraInfo){
            if(extraInfo.portal) this.portal = true;
            if(extraInfo.isRepaint) this.isRepaint = true;
        }

        // 这里不能使用 setProps 因为setProps会延迟更新数据，这边需要保证数据可以立即同步
        runInAction(() => {
            this.builders = getBuilderItems(props, this.key);
            this.props = props;
            this.domProps = this.getProps();
        })
    }
}