/**
 * 解析context defaultProps 默认参数
 */
const getDefaultProps = (source: SourceFile) => {
    const [node] = source.getExportAssignments();
    if (!node) return '';
    const [call] = node.getChildrenOfKind(SyntaxKind.CallExpression);
    if (!call) return '';
    const list = call.getChildrenOfKind(SyntaxKind.SyntaxList);
    for (const item of list) {
        const text = item.getText();
        if (/^\{(.|\n)*}$/.test(text)) {
            return text;
        }
    }
    return '';
}

