/**
 * 查找未使用的imports
 */
export const analyzeFileImports = (fileContent: string, objImports: any) => {
    const project = new Project({ useInMemoryFileSystem: true });
    const sourceFile = project.createSourceFile('temp.tsx', fileContent, {});

    // 查找是否使用了 imports 参数
    const loop = (node: Node) => {
        const children = node.getChildren();
        for (const item of children) {
            switch(item.getKind()){
                case SyntaxKind.ImportDeclaration:
                    break;
                case SyntaxKind.Identifier:
                    const name = item.getText();
                    if(objImports[name]) delete objImports[name];
                break;
                default: 
                    loop(item);
            }
        }
    }
    loop(sourceFile)

    return objImports;
}

/**
 * 删除文件无效import
 */
export const analyzeFile = (fileContent) => {
    const project = new Project({ useInMemoryFileSystem: true });
    const sourceFile = project.createSourceFile('temp.tsx', fileContent, {});

    const objImports: Record<string, { isDefault: boolean, node: any, modules?: any[] }> = {};
    // 获取所有的导入声明
    const importDeclarations = sourceFile.getImportDeclarations();

    // 遍历每一个导入声明
    importDeclarations.forEach(importDeclaration => {
        // 获取默认导入（如果有的话）
        const defaultImport = importDeclaration.getDefaultImport();

        const defaultText = defaultImport? defaultImport.getText() : getUuid();
        // 检查默认导入是否被使用( 如果没有，生产不再展示 )
        objImports[defaultText] = {
            node: importDeclaration,
            isDefault: true,
            modules: []
        };
        // 获取命名导入
        const namedImports = importDeclaration.getNamedImports();
        namedImports.forEach(specifier => {
            const variableName = specifier.getName();
            objImports[defaultText].modules.push(variableName);
            objImports[variableName] = { isDefault: false, node: specifier };
        });
    });

    // 查找是否使用了 imports 参数
    const loop = (node: Node) => {
        const children = node.getChildren();
        for (const item of children) {
            switch(item.getKind()){
                case SyntaxKind.ImportDeclaration:
                    break;
                case SyntaxKind.Identifier:
                    const name = item.getText();
                    if(objImports[name]) delete objImports[name];
                break;
                default: 
                    loop(item);
            }
        }
    }
    loop(sourceFile)

    const importList = Object.keys(objImports);

    for (const key of importList) {
        const item = objImports[key];
        if(item.isDefault){ // 判断是否为默认导出
            const { modules } = item;
            if(modules.every((key) => objImports[key])){
                // 所有引入都没有使用
                item.node.remove();
            }else if(modules.length){
                modules.forEach((key) => {
                    if(objImports[key]){
                        objImports[key].node.remove();
                    }
                })
            }
        }
    }

    // console.log('objImports', objImports)

    // 返回删除未使用导入后的代码
    return sourceFile.getFullText();
}