/**
 * 将js文本转为可识别js代码
 */
export const jsStringToJs = (value) => {
    const str = value.replace(/(\$j\{)|\s|\}/g, "");
    return decodeURIComponent(str);
}


/**
 * 将js代码转为js文本
 */
export const jsTojsString = (value) => {
    if(!value || typeof value !== 'string') return value;   // 有可能为空文本
    const str = encodeURIComponent(value);
    return `$j{ ${str} }`;
}


/**
 * 将ts代码转为js文本
 */
export const tsTojsString = (value) => {
    // await loadScript(config.typescriptURL);
    // 使用 TypeScript 进行类型检查和转换
    const transformedCode = ts.transpileModule(value, {
        compilerOptions: {
            target: ts.ScriptTarget.ESNext,
            module: ts.ModuleKind.CommonJS,
            jsx: ts.JsxEmit.React,
            useDefineForClassFields: true,
        },
    });

    return transformedCode;
}



/**
 * 将js 代码转为 props 可以接受规则
 */
export const jsVarToRuleVar = (value) => {
    console.log('jsVarToRuleVar', value)
    const tsNode = tsTojsString(`const _result = ${value}`);
    const text = tsNode.outputText;
    console.log('jsVarToRuleVar-text', text)
    const fun = new Function('', `${text}; return result;`);
    try {
        const valData = fun();
        if(valData && typeof valData == 'object'){
            let valString = JSON.stringify(valData);
            if(JSON.stringify(JSON.parse(valString)) == valString){
                // JOSN 转换可以去除函数，等无法字符串保存类型
                return jsTojsString(value);
            }
        }else {
            return valData;
        }
    }catch {
        // 无法转换的数据，直接按字符串文本保存
        return jsTojsString(value)
    }
}

const isFunStrFunction = (fnStr) => {
    return /^\(.*\)\s*=>/.test(fnStr.trim());
}

/**
 * js 函数校验
 */
export const jsFunctionToString = (value: string) => {
    const getError = () => {
        return `() => {
            // 当前函数报错，源代码如下
            ${value.split('\n').map((str) => `\n// ${str}`).join('')}
        }`
    }
    if(!isFunStrFunction(value)){
        return getError();
    }
    
    try {
        const tsNode = tsTojsString(value);
        const str = tsNode.outputText;
        // 检测是否存在语法错误
        const result = (new Function(`return ${str}`))();
        return value;
    }catch(e) {
        console.log('Error', e)
        return getError();
    }

}