/**
 * 表单相关配置
 */
export interface functionFormConfig {
    // 指定当前操作的表单
    key?: string;
    // 操作事件  提交、重置
    eventType?: "submit" | "reset";
    // 操作成功是否返回上一页
    goBack?: boolean;
    // 操作成功提示文案
    successText?: string;
}

export const methodOptions = [
    { label: "get", value: MethodType.GET },
    { label: "post", value: MethodType.POST },
    { label: "put", value: MethodType.PUT },
    { label: "del", value: MethodType.DELETE },
]

/**
 * api 相关配置
 */
export interface functionApiConfig {
    // 请求接口地址
    url?: string;
    // 请求接口类型
    method?: MethodType;
    // 请求参数
    body?: jsonItem[];
    // 成功提示
    successText?: string;
}

export interface functionConfig {
    type: functionTypes;
    // 跳转地址
    url?: string;
    // 跳转地址参数
    urlParams?: jsonItem[];
    // 表单配置
    forms?: functionFormConfig;
    // 接口配置
    api?: functionApiConfig;
    // 子事件
    all?: functionConfig[];
}



