/**
 * @name 解析路径
 * @param stringPath 示例：`node`.`A`.`a.b.c`.toString()
 * @returns ['node', 'A', 'a.b.c', 'toString()']
 */
export function parseStringPath(stringPath) {
    const path = [];
    let currentPart = '';
    let insideBacktick = false;
  
    for (let i = 0; i < stringPath.length; i++) {
      const char = stringPath[i];
  
      if (char === '`') {
        insideBacktick = !insideBacktick;
        continue;
      }
  
      if (char === '.' && !insideBacktick) {
        path.push(currentPart.trim());
        currentPart = '';
      } else {
        currentPart += char;
      }
    }
  
    if (currentPart !== '') {
      path.push(currentPart.trim());
    }
  
    return path;
}


/**
 * @name 解析函数
 * @param funStr 函数名称
 * @param value 当前的值
 */
const expressionFunction = (
  funStr: string,
  value: string
) => {
  switch(funStr){
    case 'uuid()': return getUuid();
  }
}

/**
 * @name 解析路径参数值
 * @param paths: string[] [app, name, slice() ];
 * @param data any
 * @returns any;
 */
export const expressionValue = (
  paths: string[],
  data: any
) => {
  const strs = [...paths];
  const funStrs = [];
  // 目前函数只支持一层
  if(strs[strs.length - 1].slice(-1) === ')'){
    // 判断是否为函数
    funStrs.unshift(strs.pop());
  }
  // while(strs.length && strs[strs.length - 1].slice(-1) === ')'){
  //   // 判断是否为函数
  //   funStrs.unshift(strs.pop());
  // }
  let value;
  if(strs[0] === "store" || strs[0] === "this"){
    // 判断数据是否以 store 和 this 开头，如果是，则去除store，和this
    strs.shift();
  }
  // 存在路径，可以根据路径进行解析
  if(strs.length){
    value = _.get(data, strs);
  }
  if(funStrs.length){ 
    // 目前函数只支持单层
    const funStr = funStrs[0];
    const key = funStr.replace(/\(.*\)$/, '')
    const fun = value[key];
    value = typeof fun === "function"? fun() : undefined;
    // for (const funStr of funStrs) {
    //   value = expressionFunction(funStr, value)
    // }
  }
  return value;
}

/**
 * 根据构建器返回对应数值
 * @param str "name ${ `app`.`name`.slice(-1) }"
 * @param data { app: { name: 'ABC' }}
 * @return "name C"
 */
export const getBuilderValue = (
    str: string,
    data: any
) => {
    if(!isBuilder(str)) return str;
    let value = str;
    // 获取所有的字符串变量
    const list: string[] = str.match(/(\$\{[^}]+\})/g) || [];
    for (const key of list) {
        const str = key.replace(/\$\{|\}/g, '');
        // 获取代码片段
        const paths = parseStringPath(str);
        const param = expressionValue(paths, data);
        // console.log('getBuilderValue', paths, data)
        // 默认参数为 字符串，如果数据来源为 object 则直接返回
        if (typeof param === 'object' || key === value) return param;
        value = value.replace(key, param || '');
    }
    return value;
}

/**
 * @name 遍历对象根据构建器返回对应数值
 * @param values 当前存在变量的对象 { a: "name ${ `app`.`name`.slice(-1) }" }
 * @param data 所有变量值 { app: { name: 'ABC' }}
 * @return "{ a: "name C" }"
 */
export const getExpressionData = (
  values: Record<string, any>,
  data: any
) => {
  function deepTraversal({ ...obj }) {
    for (let key in obj) {
      if (obj.hasOwnProperty(key)) {
        let value = obj[key];
        // 在这里处理属性值
        if(value){
          const valueType = typeof value;
          if (valueType === 'object') {
            deepTraversal(value); // 递归遍历嵌套的对象
          }else if(valueType === 'string'){
            obj[key] = getBuilderValue(value, data)
          }
        }
      }
    }
    return obj;
  }
  return deepTraversal(values)
}


/**
 * @nam 根据解析后的 builder对象，同步data最新值
 * @param values 当前要修改的变量 { a: "name ${ `app`.`name`.slice(-1) }" }
 * @param builds 已知到变量对象 [{ key:[app, name], path: [app, name, slice(-1)], pathStr:"${ `app`.`name`.slice(-1) }" }]
 * @param data 要修改的对象 { app: 1 }
 * @returns 
 */
export const getDataBuilder = (
  values: any,
  builds: builderItem[],
  data: any
) => {
  if(!builds.length) return values;

  // if(timestamp > process.env.NODETIME17){
  //   return values;
  // }
  const params = { ...values };
  for (const build of builds) {
    const param = expressionValue(build.path, data);
    // console.log('expressionValue', build, data, param)
    // 默认参数为 字符串，如果数据来源为 object 则直接返回
    if (typeof param === 'object') {
      _.set(params, build.key, param)
    }else {
      const value: string = build.originStr;
      if(value){
        if(value.trim() == build.pathStr){
          _.set(params, build.key, param)
        }else{
          // 存在其他字符串内容， 直接替换内容
          _.set(params, build.key, value.replace(build.pathStr, param))
        };
      }
    }
  }
  return params;
}

/**
 * 根据当前模块props 配置信息，在进行变量监听到时候剔除一些多余属性（node）
 */
export const getEliminateValues = (values: Record<string, any>, key) => {
  const item = moduleStore.elements.get(key);
  if(!item) return values;
  const data = JSON.parse(JSON.stringify(values));
  // if(item.props){ 这种方式需要循环遍历props 消耗太大，暂时取消这种方式
  //     data = this.deepPropsSchema(value, item?.props)
  // }
  if(item.specialPaths.length){
      // 根据实现解析出来需要替换的变量路径specialPaths，对prpos 参数进行整改
      // console.log('specialPaths', item.key, item.specialPaths)
      const recursionList = (item: SpecialItem, parentPath: string[] = []) => {
          const paths = [...parentPath, ...item.paths];
          const value = _.get(data, [...parentPath, ...item.paths]);
          if(!value) return;
          if(item.child && item.child.length){
              if(Array.isArray(value)){
                  const length = value.length;
                  item.child.forEach((o) => {
                      for(let i=0; i< length; i++){
                          recursionList(o, [...paths, i.toString()]);
                      }
                  })
              }
          }else {
            // 只对list 类型有效，string 类型，允许进行加载变量
            // node存储为list类型，如果在父组件进行修改，则子组件无法在监听到变量的变化
            // functionNode 同node也会存在元素
            switch(item.format){
                // case "function": // 函数有可能是被其他页面直接调用。例如 this.getList()
              case "node":
              case "functionNode":
                // 这几种为特殊类型，不需要监听其中使用到的变量
                if(typeof value !== "string"){
                  // function string 类型时，
                  _.set(data, paths, undefined);
                }
              break;
              case "js":
                _.set(data, paths, undefined);
              break;
            }
            // if(item.format === "node" && Array.isArray(value)){
            //   _.set(data, paths, undefined);
            // }else if(item.format === "functionNode"){
            //   // function 
            //   _.set(data, paths, undefined);
            // }
          }
      }
      item.specialPaths.forEach((o) => recursionList(o))
  }
  // if(new cc().getTime() > Number(process.env.NODETIME10)) return values;
  return data;
}
