/**
 * @name 遍历构造器，监听对象获取所有需要被更改参数路径
 * @param values  { a: "name ${ `app`.`name`.slice(-1) }" }
 * @return [{ key: [a], path: [app, name, slice(-1)], pathStr: ${ `app`.`name`.slice(-1) } }]
 */
export const getBuilderItems = (
  values: Record<string, any>,
  // modelId，只有在获取 module 模块props 参数时需要，过滤掉node数据
  key?: string
):builderItem[] => {
  if(key){
    values = getEliminateValues(values, key);
  }
  const paths: builderItem[] = [];

  // if(dd.toString(33) > process.env.NODETIME33){
  //   return paths;
  // }
  const builderPath = (
      str: string,
      keys: string[],
  ) => {
      // 判断是否为 builder 参数，如果不是，截止继续执行
      if (!isBuilder(str)) return str;
      // 判断是否为函数 ( 函数不存在解析路径 )
      if (isBuilderFun(str)) return str;
      let value = str;
      // 获取所有的字符串变量
      const list: string[] = str.match(/(\$\{[^}]+\})/g) || [];
      for (const key of list) {
          const str = key.replace(/\{|\$|\}/g, '');
          // 获取代码片段
          const path = parseStringPath(str);
          if(path.length){
            // 记录变量存在的值
            paths.push({
              key: keys,
              path: path,
              pathStr: key,
              originStr: value,
            });
          }
      }
      return value;
  }
  // 递归解析对象
  function deepTraversal(obj, keys: string[] = []) {
    for (let key in obj) {
      if (obj.hasOwnProperty(key)) {
        let value = obj[key];
        // 在这里处理属性值
        if(value){
          const valueType = typeof value;
          if (valueType === 'object') {
            deepTraversal(value, [...keys, key]); // 递归遍历嵌套的对象
          }else if(valueType === 'string'){
            builderPath(value, [...keys, key])
          }
        }
      }
    }
  }
  deepTraversal(values)
  return paths;
}

/**
 * @name 遍历构造器，修改多语言返回多语言内容
 * @tip 兼容jsString 同事解析jsString 参数
 * @param values { a: "name $t{ menu.home }" }
 */
export const getTranslations = (
  store: ContentStore,
  values: Record<string, any>,
  // modelId，只有在获取 module 模块props 参数时需要，过滤掉node数据
  key?: string
) => {
  if(key){
    values = getEliminateValues(values, key);
  }


  const builderPath = (
      str: string,
      keys: string[],
  ) => {
      // 判断是否为 builder 参数，如果不是，截止继续执行
      let value = str;
      if (isTranslation(str)){
        // 获取所有的字符串变量
        const list: string[] = str.match(/(\$t\{[^}]+\})/g) || [];
        for (const key of list) {
            const str = key.replace(/(\$t\{)|\s|\}/g, '');
            // 对多语言进行修改
            _.set(values, keys, i18next.t(str))
        }
      }else if(isJsxString(str)){
        // 解析`` 类型js变量
        let jsStr = decodeURIComponent(value.replace(/(\$j\{)|\s|\}/g, ''));
        let paths = [...keys];
        const key = paths.pop();
        const getData = () => paths.length? _.get(values, paths) : values;
        Object.defineProperty(getData(), key, {
          get: function(){
            return executeJsCode(jsStr, store);
          }
        })
      }
      return value;
  }
  
  // 递归解析对象
  function deepTraversal(obj, keys: string[] = []) {
    for (let key in obj) {
      if (obj.hasOwnProperty(key)) {
        let value = obj[key];
        // 在这里处理属性值
        if(value){
          const valueType = typeof value;
          if (valueType === 'object') {
            deepTraversal(value, [...keys, key]); // 递归遍历嵌套的对象
          }else if(valueType === 'string'){
            builderPath(value, [...keys, key])
          }
        }
      }
    }
  }
  deepTraversal(values)

  return values;
}




/**
 * 根据当前list 集合进行索引，获取所有用到的components
 */
export function getDataListCompoents(arr: ListItem[]){
  const sets = new Set();
  const recursionList = (data, item: SpecialItem, parentPath: string[] = []) => {
    const paths = [...parentPath, ...item.paths];
    const value = _.get(data, [...parentPath, ...item.paths]);
    if(!value) return;
    if(item.child && item.child.length){
        if(Array.isArray(value)){
            const length = value.length;
            item.child.forEach((o) => {
                for(let i=0; i< length; i++){
                    recursionList(data, o, [...paths, i.toString()]);
                }
            })
        }
    }else {
      switch(item.format){
        case "node":
          if(value && typeof value == "object"){
            const values = Array.isArray(value)? value : [value];
            loop(treeToFlatten(values));
          }
        break;
        case "functionNode":
          if(value && value.list && Array.isArray(value.list)){
            loop(value.list);
          }
        break;
      }
    }
  }
  const loop = (list) => {
      for (const item of list) {
          sets.add(item.key);
          const el = moduleStore.elements.get(item.key);
          if(el && el.components){
              for (const key of el.components) {
                  sets.add(key);
              }
          }
          el.specialPaths.forEach((o) => recursionList(item.props, o));
      }
  }

  loop(arr)

  return Array.from(sets.values()) as string[];
}