const cacheKey = 'custom-page'

export interface ConstructorProps {
  // 当前组件唯一标识
  uid?: string;
  // 当前页面或组件名称
  name?: string;
  // 是否展示操作栏
  control?: boolean;
  // 是否为node节点类型 对应 ReactNode 类型列入 <Button />
  nodeContent?: boolean;
  // 是否为module模块类型 custom 自定义模块
  isComponent?: boolean;
  // 是否为函数 对应 (a,b) => ReactNode
  isFunction?: boolean;
  // 生产构建标识
  isBuild?: boolean;
  // 限制使用组件，只允许加载以下的组件
  moduleFilterIds?: string[];
  // 可以自定义侧边栏输入框内容
  widgets?: FormGeneragteProps['widgets'];
}
class Store {
  type = 'template';
  uid: string = getUuid();
  name: string = '';
  getIndex(){
    if(!this.list.length) return 1;
    return Math.max.apply(Math, this.list.map((o) => Number(o.id.slice(1)) || 1)) + 1;
  }

  parse: ParseStore;

  // 双击点击某组件
  onDoubleClick?: (item: ModuleItem) => void;
  // 是否允许子级拖动
  childDrag?: boolean = true;



  // 限制组件id， 指定使用指定的组件
  moduleFilterIds?: string[];



  // list Map 节点
  nodeMap: Map<string, ListItem> = new Map();
  // 页面组件集合
  @observable list: ListItem[] = [];
  mapStore = new Map<string, DropDragStore>();
  addMapStore = (id: string, data: any) => this.mapStore.set(id, new DropDragStore({ ...data, page: this }));
  // 序列化node集合
  @computed get nodeList() {
    // 记不清 convertToTree 为啥合并时不去除 children , 所以这边要把children 去除掉
    return convertToTree(toJS(this.list.map(({ children, ...item }: any) => item)), 'id', 'parentId');
  }

  
  // 修改页面组件
  @action
  setList = (list) => {
    this.list = list;
    this.nodeMap = new Map(list.map((o) => [o.id, o]));
    // console.log('this.index', this.index, list.map((o) => Number(o.id.slice(1)) || 1))
    // console.log(JSON.stringify(list.map((o) => _.pick(o, ['id', 'parentId', 'children']))));
  };


  /**
   * 获取list 信息，同步了props 参数
   */
  getDataList = (list: ListItem[]) => {
    return list.map((o) => {
      const element = moduleStore.elements.get(o.key);
      const store = this.mapStore.get(o.id) || o;
      // @ts-ignore
      delete o.children;
      const option = {
        ...o,
        props: toJS(store.props)
      }

      return option;
    })
  }

  // 返回页面数据 
  getData = (): pageDataProps => {
    // 组件数据获取
    const list = this.getDataList(this.list);
    // console.log('functionNode-node-data1', _.cloneDeep(list))
    if(this.isFunction || this.nodeContent){
      // 函数组件和node集合对应type ReactNode || () => ReactNode, 均不存在css
      this.lessStr = undefined;
      this.cssStr = undefined;
    }
    let components = getDataListCompoents(list);

    if(this.page.elements){
      for (const element of this.page.elements) {
        const keys = getDataListCompoents(element.list || []);
        components = components.concat(keys);
      }
    }


    return {
      components: Array.from(new Set(components)),
      cssStr: this.cssStr,
      lessStr: this.lessStr,
      // 页面数据
      page: toJS(this.page),
      // 页面组件数据
      list: toJS(list),
    }
  }

  // 更新组件数据
  setData = async ({ page, list, lessStr }: Partial<pageDataProps>) => {
    if(page) this.setPage(page)
    if(lessStr) await this.setLess(lessStr);
    
    if(!list) return;
    // this.mapStore.clear(); // 清空组件实例(防止重复);
    
    const getModuleList = (ids) => {
      return config.api.getModuleList(ids);
    }
    // console.log('list', list)
    list.forEach((o) => { o.key = o.key.toString() });

    const ids = list.filter((o) => !moduleStore.elements.has(o.key)).map((o) => o.key);
    if(ids.length){
      // 模块未加载
      const modules = await getModuleList(ids);
      await moduleStore.setElements(modules);
      this.setList(list);
    }else {
      this.setList(list);
    }
  }


  


  control: boolean = true;
  nodeContent: boolean = false;
  isComponent: boolean = false;
  isBuild: boolean = false;
  isFunction: boolean = false;
  widgets: any = {};

  get isPage(){
    return !this.isComponent && !this.nodeContent && !this.isFunction
  }

  constructor({ 
    uid,
    name,
    moduleFilterIds,
    control = true,
    isComponent = false,
    isBuild = false,
    nodeContent = false,
    isFunction = false,
    widgets
  }: ConstructorProps = {}){
    makeObservable(this);
    this.control = control;
    this.nodeContent = nodeContent;
    this.isComponent = isComponent;
    this.isFunction = isFunction;
    this.isBuild = isBuild
    if(uid) this.uid = uid;
    if(name) this.name = name;
    if(moduleFilterIds){
      this.moduleFilterIds = moduleFilterIds;
    }
    if(widgets){
      this.widgets = widgets;
    }
    if(config.parse){
      this.parse = new ParseStore({ store: this })
    }
  }




  /**
   * @name 添加元素
   * @param item 添加list单项
   * @param insertId 接收节点的id
   * @param position 接口的位置信息
   */
  addList = async (
    item: ModuleItem,
    insertId?: string,
    position: insertPosition = insertPosition.children,
  ) => {
    await moduleStore.syncModuleIds([item.key, ...(item?.extraInfo?.components || [])]);
    let list = [...this.list];
    const props = item.extraInfo?.initialProps || {};

    // console.log('item.extraInfo', item, this.list);
    const option: ListItem = { 
      ..._.pick(item, ['key', 'name', 'nickname']),
      props: getExpressionData(props, {}),
      // id: `u${this.getIndex()}`,
      id: getUuid("hash"),
    };
    // console.log(this.getIndex(), toJS(this.list))
    if(insertId){
      const index = list.findIndex((o) => o.id === insertId);
      if(index !== -1){
        option.parentId = list[index].parentId;
        // 判断节点插入位置
        // console.log('position', position, index)
        switch(position){
          case insertPosition.children:
              option.parentId = insertId;
              list.push(option);
            break;
          case insertPosition.prev:
            list.splice(index, 0, option);
          break;
          case insertPosition.next:
            list.splice(index + 1, 0, option);
        }
      }
    }else {
      list.push(option);
    }
    // console.log('options', option, item)
    this.setList(list);
  };

  /**
   * @name 更新元素
   * @param data 添加list单项
   * @param insertId 接收节点的id
   * @param position 接口的位置信息
   */
  updateList = (
    data: ListItem,
    insertId?: string,
    position: insertPosition = insertPosition.children,
  ) => {
    let list = toJS(this.list);
    // 从列表中删除当前阶段
    list.splice(list.findIndex((o) => o.id === data.id), 1);
    if(position === insertPosition.children){
      data.parentId = insertId;
      list.push(data);
    }else {
      const index = list.findIndex((o) => o.id === insertId);
      data.parentId = list[index].parentId;
      switch(position){
        case insertPosition.prev:
          list.splice(index, 0, data);
        break;
        case insertPosition.next:
          list.splice(index + 1, 0, data);
        break;

      }
    }
    this.setList(list)
    // let list = Array.from(this.mapList.values());
  };

  // 删除list单项
  deleteList = (id: ListItem['id']) => {
    this.setList(deleteNode(this.list, id))
  }

  // 复制指定节点
  copyList = (id: ListItem['id']) => {
    const list = findNode(this.list, id);
    // 替换id 和 parentId
    const ids = {};
    const result = list.map((o) => {
      if(!ids[o.id]) ids[o.id] = getUuid('hash');
      if(o.parentId && !ids[o.parentId]) ids[o.parentId] = getUuid('hash');
      // 将组件最新数据赋能
      const store = this.mapStore.get(o.id) || o;
      if(o.id === id) return { ...o, id: ids[o.id], props: toJS(store.props) };
      return {
        ...o,
        props: toJS(store.props),
        id: ids[o.id],
        parentId: ids[o.parentId]
      }
    })
    const index = this.list.findIndex((o) => o.id == id);
    const resultList = [...this.list];
    resultList.splice(index + 1, 0, ...result);
    this.setList(resultList);
    console.log('copyList', resultList);
  }

  // 当前正在拖动的模块
  @observable moveId = '';
  @action
  setMoveId = (id) => {
    this.moveId = id;
  };


  // 当前选中的模块
  @observable selectId = '';

  setSelectId = (id) => {
    if(this.selectId == id) return;
		this.selectId = id;
  }
  @computed get selectItem(){
    if(!this.selectId) return null;
    const item = this.list.find((o) => o.id === this.selectId);
    if(!item) return null;
    const element: any = moduleStore.elements.get(item.key);
    return element;
  }

  /**
   * 页面设置参数
   */
  @observable page: pageProps = {
    style: {
    },
    className: "",
  }
  

  contentData: PageStore = {} as any //new PageStore({ page: this.page }).getStore();


  @action
  setPage = (page: pageProps) => {
    const element = moduleStore.elements.get(this.uid);
    this.page = page;
    this.contentData = new PageStore({ page: toJS(this.page)  }).getStore();
    // if(element){
    //   if(element.extraInfo.defaultProps){
    //     this.contentData.props = element.extraInfo.defaultProps;
    //   }
    //   Object.assign(element.extraInfo, page.extraInfo)
    // }
  }

  lessStr: string = '';
  cssStr: string = '';


  setCss = (css: string) => {
    this.cssStr = css;
    addCSS(css, this.uid);
  }

  setLess = async (lessStr: string) => {
    this.lessStr = lessStr;
    await loadScript(config.lessURL).then(() => {
      return less.render(lessStr).then((res) => {
        this.setCss(res.css);
      });
    })
  }


  @observable jsxRender = '';
  @action setJsxRender = (str) => {
    this.jsxRender = str;
  }

	/**
	 * 生成当前页面jsx 函数（部署方法）
	 */
	getRenderText = async () => {
		const text = generateModuleRenderText(this);
    // return transformToEs2015(text);
    const list = await filePrettier([text]);
    this.setJsxRender(list[0])
    return list[0];
	}

  

  /**
   * 获取当前页面文本列表（ index.tsx、store.tsx ) 文件
   */
  getTextFiles = async () => {
    const { indexText, storeText } = await getPageToFileData(this);
    const data = await filePrettier([indexText, storeText]);

    if(this.isBuild){
      return {
        indexText: await analyzeFile(data[0]),
        storeText: await analyzeFile(data[1]),
      }
    }
    return {
      indexText: data[0],
      storeText: data[1],
    }
  }


  /**
   * 获取当前页面jsx Body
   */
  getPageJsxBody = () => {
    return getPageJsxBody(this.getData().list);
  }


  /**
   * 完成Index 文件解析
   */
  parsePageIndexText = (text: string) => {
    return new Promise(async (resolve, reject) => {
      try{
        const data = await getTypeData(text);
        const pageStore = await JsxToPageList(data, this);
  
        if(pageStore){
          let pageData = pageStore.data || [];
          pageData = Array.isArray(pageData)? pageData : [pageData];
          const element = moduleStore.elements.get(this.uid);
          if(element){
            _.set(element, ['extraInfo', 'isRef'], pageStore.isRef)
            if(pageStore.refFunction){
              _.set(element, ['extraInfo', 'refBody'], pageStore.refFunction)
              _.set(element, ['extraInfo', 'refProps'], pageStore.refProps)
            }
            _.set(element, ['extraInfo', 'defaultProps'], pageStore.defaultProps);
            if(pageStore.defaultProps){
              // _.set(element, ['extraInfo', 'defaultProps'], pageStore.defaultProps);
              // this.contentData.props = pageStore.defaultProps;
            }
            _.set(element, ['extraInfo', 'initialProps'], pageStore.initialProps);
            this.page.extraInfo = {
              defaultProps: pageStore.defaultProps,
              initialProps: pageStore.initialProps,
            }
            if(pageStore.refFunction || pageStore.defaultProps){
              moduleStore.updateElement(this.uid, element);
            }
          }
          const list = treeToFlatten(pageData);
          // console.log('page', this, list)
          this.setData({ list, page: { ...this.page, ...pageStore.page } })
          resolve(true);
        }else {
          reject("Error：pageStore null")
        }
      }catch(e){
        console.error(e)
        reject(`Error：${e.message}`);
      }
    })
  }

  /**
   * 完成store 文件解析
   */
  parsePageStoreText = (text: string) => {
    return new Promise(async (resolve, reject) => {
      const data = await getTypeData(text);
      const pageData = await storeToPageData(data, this);
      if(pageData){
          // 更新页面数据
          this.setData({ page: { ...this.page, ...pageData }});
          resolve(true);
      }else{
        reject("保存失败，找不到Store 类")
      }
    })
  }
  
  /**
   * schema 解析
   */
  allSchemaToType = async (list: JSONSchema[]) => {
    return Promise.all(list.map((o) => schemaToType(o)))
  }

}

export default Store;
