import React, { ReactNode, memo, useContext, useMemo, useState } from 'react';
import { FormGenerateItem, FormItem } from './interface';
import {
  Collapse,
  Grid,
  FormItemProps,
  Card,
  Modal,
  Form,
  FormInstance,
  Button,
  ModalProps,
} from '@arco-design/web-react';
import FormItemRender from './components/FormItem';
import _ from 'lodash';
import { IconArrowFall, IconArrowRise, IconDelete, IconDown, IconUp } from '@arco-design/web-react/icon';
import { isVerifySync } from 'src/utils/verify';
import { toJS } from 'mobx';
import Store from './store';
import { useObserver } from 'mobx-react-lite';
import TableEditor, { TableEditorProps } from './components/TableEditor';
import Context from './context';
import './style.less';
import { formFields } from 'src/types/schema';
import RefSchema from './components/RefSchema';
const { Row, Col } = Grid;

export interface FormGeneragteProps extends FormGenerateItem {
  form?: FormInstance;
  store?: Store;
  fieldKey?: string;
  tableProps?: TableEditorProps;
  getLabelField?: (o: FormItem) => ReactNode;
}

// const ICONVIE: any = (props) => JSON.stringify(props);

/**
 * @title 根据formItemList 组合生成表达，支持children 对象，和 list 集合表单生成
 * 对象集合可选择组合方式，默认组合Card， 可选择 modal 组合方式
 */
const FormGeneragte = ({
  form,
  title,
  to,
  cardProps,
  modalProps,
  tableProps,
  rowProps = {},
  cols = 8,
  store: uStore,
  fieldKey = "formData",
  getLabelField,
  formItemProps: formProps = {},
  render,
  widgets = {},
  ...props
}: FormGeneragteProps) => {
  const formItemList = useMemo(() => {
    // 如果是modal 类型，采用新的Form 表单进行管理，优化对象结构
    if(to === "Modal") return props.formItemList.map((o) => ({ ...o, field: o.field.replace(fieldKey, "forms") }));
    return props.formItemList;
  },[props.formItemList])

  // console.log('FormGeneragte', formItemList);
  const [store] = useState<Store>(() => uStore || new Store());
  let Element: any = useMemo(() => {
    if(title || cardProps || modalProps){
      // 判断首页要使用的组件类型
      switch(to){
        case 'Modal':
          return (props: any) =>{
            return useObserver(() => {
              const key = "forms";
              const visible = Boolean(store.data[fieldKey]);
              const context = useContext(Context);
              const [mForm] = Form.useForm();
              // 优先从mForm 表单中获取， 防止多层嵌套问题
              const pForm = context.form || form;
              const setVisible = (bool) => {
                store.setData(fieldKey, bool);
              }
              // 采用初始值方式赋值，form.setFieldValue有bug在深度层级下无法赋值
              const data = useMemo(() => {
                return {
                  [key]: pForm.getFieldValue(fieldKey)
                }
              },[visible])


  
              return (
                <Context.Provider value={{ form: mForm, formats: context.formats }}>
                  <Button type="primary" onClick={() => setVisible(true)}>编辑</Button>
                  <Modal
                    title={title}
                    visible={visible}
                    focusLock={false}
                    onCancel={() => {
                      setVisible(false)
                    }}
                    onOk={() => {
                      try{
                        // console.log('OK', mForm.getFieldsValue(), mForm.getFields())
                        mForm.validate().then(() => {
                          const value = mForm.getFieldValue(key);
                          const innerSetFieldValue = pForm.getInnerMethods(true).innerSetFieldValue;
                          innerSetFieldValue(fieldKey, value);
                          setVisible(false)
                        })
                      }catch{
                        // setVisible(false)
                      }
                    }}
                    unmountOnExit
                    {...modalProps} {...props}
                  >
                    <Form
                      layout="vertical"
                      wrapper="div"
                      initialValues={data}
                      form={mForm}
                    >
                      {props.children}
                    </Form>
                  </Modal>
                  <Form.Item noStyle field={fieldKey}><span /></Form.Item>
                </Context.Provider>
              )
            })
          }
        break;
        default:
          return (props: any) => (
            <Card 
              title={title}
              bordered={false}
              {...cardProps}
              {...props} 
            />
          )
      }
    }
  },[cardProps]);

  if (render) {
    if (Element) {
      return (
        <Element>
          {render}
        </Element>
      );
    } else {
      return render;
    }
  }

  const renderList = useMemo(() => {
    if (Array.isArray(formItemList)) {
      const renderFormItemList = (list: FormItem[]) => {
        const render = list.map((item, i) => {
          const key = Math.random();
          // console.log('item-1-start', key, JSON.parse(JSON.stringify(item)))
          let rules: FormItemProps['rules'];
          if (item.required) {
            rules = [{ required: true, message: '该字段不能为空' }];
          }
          if (item.rules) {
            rules = item.rules;
          }
          const formGenerateProps = item.formGenerateProps as FormGenerateItem || {};
          const formItemProps: FormItemProps = {
            shouldUpdate: item.shouldUpdate,
            rules,
            field: item.field,
            label: item.label,
            ...formProps,
            ...item.formItemProps,
          }
          if('noStyle' in item) formItemProps.noStyle = item.noStyle;
          if(getLabelField){
            formItemProps.label = getLabelField(item)
          }
          const field = `${item.field}`;
          let FormItem: any = (props: any) => (
            <Col key={i} span={item.colSpan || cols} {...item.colProps}>
              {props.children}
            </Col>
          );
          // 解析Ref 引用
          if(item.valueType  === formFields.refSchema){
            return (
              <RefSchema
                key={field}
                field={formItemProps.field as string}
                renderFormItemList={renderFormItemList}
                {...item.fieldProps}
              />
            ) 
          }
          let children:any[] = [];
          if(formGenerateProps.to || item.list){
            // 除了 Card，其他设置为弹窗展示方式
            FormItem = memo((props: any) => {
              // 用户可以根据show决定是否展示，这里添加show判断
              const show = item.show;
              const { form: uForm, ...res } = useContext(Context);
              const [pField] = useState< string>(() => {
                const paths: any = field.split('.');
                if(paths.length > 1) return paths.slice(0,-1).join('.')
                return "";
              })
              // 获取最新的form
              const cForm = uForm || form;
              const geColProps = { key: i, span: item.colSpan || cols, ...item.colProps };
              const geformProps = { ...formItemProps, ...props, field: undefined };
              if(show !== undefined){
                if(typeof show === 'boolean'){
                  return show? <Col {...geColProps} key="col1"><Form.Item {...geformProps}/></Col> : null;
                }
                return (
                  <Form.Item shouldUpdate={formItemProps.shouldUpdate || true} noStyle>
                    {() => {
                        const values = cForm.getFields();
                        const data = {
                          ...(pField? _.get(values, pField) : values),
                          formData: form.getFields(),
                        };
                        if(show && isVerifySync(show, data)){
                          return <Col {...geColProps} key="col2"><Form.Item {...geformProps}/></Col>;
                        }
                        return null;
                    }}
                  </Form.Item>
                )
              }else {
                return (
                  <Col {...geColProps} key="col"><Form.Item {...geformProps} /></Col>
                )
              }
            });
          }
          // 设置了分类展示, 目前分类支持 Card 和 Modal 组件
          if((formGenerateProps.to)){
            if(item.children){
              children = item.children.map((o) => {
                return {
                  ...o,
                  formItemProps:{
                    // 0907 当前formItemProps 中配置不应该透传
                    // ...item.formItemProps,
                    label: o.label,
                    ...o.formItemProps,
                  },
                  field: `${field}.${o.field}`
                }
              })
            }else {
              // 没有子类（list类型），将当前作为子级正常渲染
              children = [ _.omit(item, ['formGenerateProps', 'show', 'colSpan', 'colProps']) ]
              // 因为只有单列，所以不再展示formItem 布局
              children[0].formItemProps = { noStyle: true }
            }
            /**
             * 生成二级对象表单
             * 默认会继承当前父级组件的参数，当然也可以进行覆盖
             */
            return (
              <FormItem key={i}>
                <FormGeneragte
                  cols={cols}
                  store={store}
                  fieldKey={field}
                  getLabelField={getLabelField}
                  title={formItemProps.title || item.label}
                  widgets={widgets}
                  modalProps={modalProps}
                  tableProps={tableProps}
                  {...formGenerateProps}
                  cardProps={{
                    bordered: true,
                    ...formGenerateProps.cardProps,
                  }}
                  rowProps={{
                    ...rowProps,
                    ...formGenerateProps.rowProps
                  }}
                  form={form}
                  formItemList={children}
                />
              </FormItem>
            )
          }

          if(item.list && (!item.widget || !widgets[item.widget])){
            // 如果用户使用了 widget 原则上widget 优先级最高
            if(item.listType === "Table"){
              return (
                <Col key={`${i}_${field}`} span={24}>
                  <TableEditor key={i}
                    form={form} item={item} field={field}
                    renderFormItemList={renderFormItemList}
                    {...tableProps}
                  />
                </Col>
              )
            }
            return (
              <FormItem key={`${i}_${field}`}>
                <Form.List field={field}>
                  {(fields, { add, remove, move }) => {
                    const getControlElements = (index)  => [
                      <Button key="remove"
                        icon={<IconDelete />}
                        shape='circle'
                        status='danger'
                        size="small"
                        style={{
                          margin: '0 8px',
                          flexShrink: 0,
                        }}
                        onClick={() => remove(index)}
                      ></Button>,
                      <Button key="move"
                        shape='circle'
                        size="small"
                        style={{
                          flexShrink: 0
                        }}
                        onClick={() => move(index, index > 0 ? index - 1 : index + 1)}
                      >
                        {index > 0 ? <IconArrowRise /> : <IconArrowFall />}
                      </Button>
                    ]
                    /**
                     * ListItem 
                     */
                    const ListItem = ({ index, option, controlElements }: any) => {
                      const [isAll, setIsAll] = useState<boolean>(false);
                      const generateProps = _.assign(formGenerateProps, item.list.formGenerateProps)
                      const column = useMemo(() => {
                        return 24/(generateProps.cols || cols);
                      },[])
                      const formItemList = useMemo(() => {
                        const list = item.list.children.map((o) => {
                          return {
                            ...o,
                            formItemProps:{
                              ...item.list.formItemProps,
                              ...o.formItemProps,
                            },
                            field: `${option.field}.${o.field}`
                          }
                        })
                        if(!isAll) return list.slice(0, column);
                        return list;
                      },[isAll])
                      const AllRender = useMemo(() => {
                        if(item.list.children.length > column){
                          if(isAll){
                            return (
                              <Button key="open" style={{ flexShrink: 0 }}
                                type="text" onClick={() => setIsAll(false)}
                              >
                                收起<IconUp />
                              </Button>
                            )
                          }else {
                            return (
                                <Button key="close" style={{ flexShrink: 0 }}
                                  type="text" onClick={() => setIsAll(true)}
                                >
                                    展开<IconDown />
                                </Button> 
                            )
                          }
                        }
                        return null
                      },[isAll])
                      return (
                        <div key={index} className="items-center-bewteen">
                          <FormGeneragte
                            cols={cols}
                            store={store}
                            fieldKey={option.field}
                            title={`${formItemProps.title || item.label}${index + 1}`}
                            widgets={widgets}
                            getLabelField={getLabelField}
                            modalProps={modalProps}
                            tableProps={tableProps}
                            {...generateProps}
                            cardProps={{
                              bordered: true,
                              extra:(
                                <>
                                  {getControlElements(index)}
                                  {AllRender}
                                </>
                              ),
                              style: { marginBottom: 10 },
                              ...cardProps,
                              ...generateProps.cardProps,
                            }}
                            rowProps={{
                              ...rowProps,
                              ...generateProps.rowProps
                            }}
                            form={form}
                            formItemList={formItemList}
                          />
                        </div>
                      )
                    }
                    // console.log('item.list', item.list)
                    return (
                      <div>
                        {
                          item.list.children? 
                          fields.map((option, index) => {
                            return <ListItem key={index} option={option} index={index} />
                          }):
                          fields.map((option, index) => {
                            return (
                              <div key={i} className='items-center' style={{ marginBottom: 10 }}>
                                <FormItemRender
                                  show={item.list.show}
                                  colProps={{
                                    span: item.list.colSpan || cols,
                                    ...item.list.colProps
                                  }}
                                  notCol
                                  formItemProps={{
                                    noStyle: true,
                                    ...formItemProps,
                                    field: `${option.field}`,
                                  }}
                                  fieldProps={item.list.fieldProps}
                                  valueType={item.list.valueType}
                                  Render={widgets[item.list.widget] || item.list.render}
                                  preValueChange={item.list.preValueChange}
                                  form={form}
                                />
                                {getControlElements(index)}
                              </div>
                            );
                          })
                        }
                        <Button
                          onClick={() => {
                            // 5.6 目前场景中针对的是 Array<object>类型
                            if(item.list.children){
                              add({}); 
                            }else {
                              add(undefined);
                            }
                          }}
                        >
                          添加
                        </Button>
                      </div>
                    )
                  }}
                </Form.List>
              </FormItem>
            )
          }


          return (
            <FormItemRender
              key={`${i}_${field}`}
              show={item.show}
              colProps={{
                span: item.colSpan || cols,
                ...item.colProps
              }}
              notCol={item.notCol}
              formItemProps={formItemProps}
              fieldProps={item.fieldProps}
              valueType={item.valueType}
              Render={widgets[item.widget] || item.render}
              preValueChange={item.preValueChange}
              form={form}
            />
          );
        });
        return render
      }

      return (
          <Row gutter={[16, 8]} {...rowProps}>
            {renderFormItemList(formItemList)}
          </Row>
      );
    }
    return null;
  }, [formItemList]);

  if (Element) {
    return (
      <Element>
        {renderList}
      </Element>
    );
  }


  return renderList;
};

export default FormGeneragte;
