import { builderItem } from "src/types/expression";
import { isBuilder, isBuilderFun } from "src/utils/is";
import _ from 'lodash';

/**
 * @name 解析路径
 * @param stringPath 示例：`node`.`A`.`a.b.c`.toString()
 * @returns ['node', 'A', 'a.b.c', 'toString()']
 */
export function parseStringPath(stringPath) {
  const path = [];
  let currentPart = '';
  let insideBacktick = false;

  for (let i = 0; i < stringPath.length; i++) {
    const char = stringPath[i];

    if (char === '`') {
      insideBacktick = !insideBacktick;
      continue;
    }

    if (char === '.' && !insideBacktick) {
      path.push(currentPart.trim());
      currentPart = '';
    } else {
      currentPart += char;
    }
  }

  if (currentPart !== '') {
    path.push(currentPart.trim());
  }

  return path;
}


/**
 * @name 遍历构造器，监听对象获取所有需要被更改参数路径
 * @param values  { a: "name ${ `app`.`name`.slice(-1) }" }
 * @return [{ key: [a], path: [app, name, slice(-1)], pathStr: ${ `app`.`name`.slice(-1) } }]
 */
export const getBuilderItems = (
    values: Record<string, any>,
  ):builderItem[] => {
    const paths: builderItem[] = [];
  

    const builderPath = (
        str: string,
        keys: string[],
    ) => {
        // 判断是否为 builder 参数，如果不是，截止继续执行
        if (!isBuilder(str)) return str;
        // 判断是否为函数 ( 函数不存在解析路径 )
        if (isBuilderFun(str)) return str;
        let value = str;
        // 获取所有的字符串变量
        const list: string[] = str.match(/(\$\{[^}]+\})/g) || [];
        for (const key of list) {
            const str = key.replace(/\{|\$|\}/g, '');
            // 获取代码片段
            const path = parseStringPath(str);
            if(path.length){
              // 记录变量存在的值
              paths.push({
                key: keys,
                path: path,
                pathStr: key,
                originStr: value,
              });
            }
        }
        return value;
    }
    // 递归解析对象
    function deepTraversal(obj, keys: string[] = []) {
      for (let key in obj) {
        if (obj.hasOwnProperty(key)) {
          let value = obj[key];
          // 在这里处理属性值
          if(value){
            const valueType = typeof value;
            if (valueType === 'object') {
              deepTraversal(value, [...keys, key]); // 递归遍历嵌套的对象
            }else if(valueType === 'string'){
              builderPath(value, [...keys, key])
            }
          }
        }
      }
    }
    deepTraversal(values)
    return paths;
}



/**
 * @name 解析路径参数值
 * @param paths: string[] [app, name, slice() ];
 * @param data any
 * @returns any;
 */
export const expressionValue = (
  paths: string[],
  data: any
) => {
  const strs = [...paths];
  const funStrs = [];
  // 目前函数只支持一层
  if(strs[strs.length - 1].slice(-1) === ')'){
    // 判断是否为函数
    funStrs.unshift(strs.pop());
  }
  // while(strs.length && strs[strs.length - 1].slice(-1) === ')'){
  //   // 判断是否为函数
  //   funStrs.unshift(strs.pop());
  // }
  let value;
  if(strs[0] === "store" || strs[0] === "this"){
    // 判断数据是否以 store 和 this 开头，如果是，则去除store，和this
    strs.shift();
  }
  // 存在路径，可以根据路径进行解析
  if(strs.length){
    value = _.get(data, strs);
  }
  if(funStrs.length){ 
    // 目前函数只支持单层
    const funStr = funStrs[0];
    const key = funStr.replace(/\(.*\)$/, '')
    const fun = value[key];
    value = typeof fun === "function"? fun() : undefined;
    // for (const funStr of funStrs) {
    //   value = expressionFunction(funStr, value)
    // }
  }
  return value;
}
  

  /**
 * @nam 根据解析后的 builder对象，同步data最新值
 * @param values 当前要修改的变量 { a: "name ${ `app`.`name`.slice(-1) }" }
 * @param builds 已知到变量对象 [{ key:[app, name], path: [app, name, slice(-1)], pathStr:"${ `app`.`name`.slice(-1) }" }]
 * @param data 要修改的对象 { app: 1 }
 * @returns 
 */
export const getDataBuilder = (
  values: any,
  builds: builderItem[],
  data: any
) => {
  if(!builds.length) return values;

  const params = { ...values };
  for (const build of builds) {
    const param = expressionValue(build.path, data);
    // console.log('expressionValue', build, data, param)
    // 默认参数为 字符串，如果数据来源为 object 则直接返回
    if (typeof param === 'object') {
      _.set(params, build.key, param)
    }else {
      const value: string = build.originStr;
      if(value){
        if(value.trim() == build.pathStr){
          _.set(params, build.key, param)
        }else{
          // 存在其他字符串内容， 直接替换内容
          _.set(params, build.key, value.replace(build.pathStr, param))
        };
      }
    }
  }
  return params;
}