
import type { FunctionNodeDataProps, ListItem, ModuleItem, pageDataProps, pageProps } from 'src/components/CustomPage/interface';
import { moduleSource, SpecialItem, TaroModuleSource } from 'src/types/module';
import Store from "src/components/container/store";
import type { IconProps } from '@arco-design/web-react/icon';
import { get as safeGet, set as safeSet } from 'lodash';
import { JSXElementConstructor, ReactElement, ReactNode, createElement, memo } from 'react';
import { toJS } from 'mobx';
import { getModuleItem, schemaFormatSpecialPath } from 'src/utils/module';
import { executeJsCode, executeSandboxedCode } from 'src/utils/function';
import NodeElement from 'src/components/CustomPage/NodeElement';
import { isBuilderFun } from 'src/utils/is';
import config from 'src/config';
import { eventProps, eventkeys, htmlElements, htmlInlineElements, htmlModuleList } from 'src/utils/database';
import { basicsModuleList, basicsNodeRender } from 'src/components/basics';
import { treeToFlatten } from 'src/utils';
import _ from 'lodash';

// html 基础元素中所有的onClick 参数
// console.log('iconss', arco)

interface elementItem extends ModuleItem {
    // 引用的组件列表
    components?: string[];
    // 当前对象中引入到的 变量数组
    specialPaths?: SpecialItem[];
    render: JSXElementConstructor<any>;
}

class ModuleStore {

    /**
     * 所有components render元素
     */
    elements: Map<string, elementItem> = new Map();

    history: History;

    constructor(){
        for (const item of basicsModuleList) {
            this.elements.set(item.key, {
                specialPaths: schemaFormatSpecialPath(item.props),
                render: basicsNodeRender[item.key],
                ...item
            })
        }
    }

    /**
     * 根据list 集合获取所有的moduleIds
     * @name 判断存在 key 或 props 既可以判断为模块
     */
    asyncPageList = async (list: pageDataProps['list']) => {
        const ids = [];
        const recursionList = (arr: pageDataProps['list']) => {
            if(!Array.isArray(arr)) return;
            for (const item of arr) {
                if(item.key && item.props && typeof item.key === 'string' && typeof item.props === 'object'){
                    ids.push(item.key);
                    for (const pKey in item.props) {
                        const value = item.props[pKey];
                        if(value && Array.isArray(value) && typeof value[0] === 'object'){
                            recursionList(value);
                        }
                    }
                }
            }
        }
        recursionList(list);
        // console.log('recursionList', list)
        return await this.syncModuleIds(ids);
    }

    /**
     * @name 根据ids同步组件列表
     */
    syncModuleIds = async (list: string[]) => {
        if(!Array.isArray(list)) return undefined;
        const ids = list.filter((key) => !this.elements.has(key));
        if(ids.length){
            // 模块未加载，需要先去加载模块信息
            const modules = await config.api.getModuleList(ids);
            // console.log('getModuleList', config.api.getModuleList, modules);
            await this.setElements(modules);
        }
    }
    
    addElement = (item: elementItem) => {
        this.elements.set(item.key, {
            ...item,
            components: item?.extraInfo?.components,
            specialPaths: schemaFormatSpecialPath(item.props)
        })
    }

    /** 更新当前组件 */
    updateElement = async (key: string, item: ModuleItem) => {
        const element: elementItem = {
            ...item,
            render: await config.modules.getRender(item),
            components: item?.extraInfo?.components,
            specialPaths: schemaFormatSpecialPath(item.props)
        }
        // if(element.source == moduleSource.context || element.source == moduleSource.custom){
        //     config.run.state.mModules[element.key] = element.render;
        // }
        this.elements.set(key, element);
    }

    /**
     * 根据ModuleItem 实现render 预渲染
     * @param list 组件列表
     */
    setElements = async (list: ModuleItem[]) => {
        // console.log('list', toJS(list))
        // 获取组件列表
        return Promise.all((list || []).map((item) => {
            return new Promise(async (resolve, reject) => {
                const { key, category, source, name, props, content, extraInfo = {} } = item;
                const schema = toJS(props);
                if(this.elements.has(key)) return resolve(true);
                await this.updateElement(key, {
                    ...item,
                    props: schema,
                })
                return resolve(true)
                
                // return reject(false);
            })
        }))
    }

    getIcon = (value, props: IconProps = {}): ReactNode => {
        return config.modules.getIcon(value);
    }

    /**
     * @name 展示内容
     * 根据 format 指定内容进行数据完善
     */
    getPropsValue = (value: string | pageDataProps, format: JSONSchema['format'], code: Store, params?: SpecialItem['params']) => {
        switch(format){
            case 'icon':
                if(typeof value === 'string') {
                    return this.getIcon(value);
                }else if(value && typeof value == "object"){
                    const values = treeToFlatten(Array.isArray(value)? value : [value] as any);
                    // 类型比较特殊，按照多里
                    return <NodeElement list={values} store={code} />
                }
            break;
            case 'function':
                if(typeof value === 'string') {
                    return executeSandboxedCode(value, code);
                }else if(typeof value === "object"){
                    // let keys = [];
                    // if(params && params.functionType && params.functionType.arguments){
                    //   keys = params.functionType.arguments.map((o) => `${o.title}: any`);
                    // }
                    return () => {};
                }
                break;
            case "functionNode":
                const valueType = typeof value;
                if(valueType === "string"){
                    return executeSandboxedCode(value, code);
                }else if(valueType === "object"){
                    return (...args) => {
                        const { params, list, countList, jsxBody } = value as FunctionNodeDataProps;
                        const getVarText = () => {
                            if(countList && countList.length){
                                return countList.filter((o) => o.countName).map((o) => {
                                    return `const ${o.countName} = ${o.countValue}`;
                                }).join('\n')
                            }
                            return "";
                        }
                        return executeSandboxedCode(
                            `(${params.map((o) => `${o}`).join(',')}) => {
                                ${getVarText()}
                    
                                return ${jsxBody}
                            }\n`,
                            code
                        )
                    }
                }
            break;
            case 'node':
                if(value && typeof value == "object"){
                    console.log('NodeElement', value)
                    const values = treeToFlatten(Array.isArray(value)? value : [value] as any);
                    // const page = new CustomPageStore({})
                    // page.setData({ list: values });
                    // return <PageContent store={page as any} />
                    // 类型比较特殊，按照多里
                    return <NodeElement list={values} store={code} />
                }
                return value;
            default:
                if(config.schema.sources[format]){
                    const { funName, default: defaultValue, type } = config.schema.sources[format];
                    if(type === "function"){
                        if(typeof value === 'string') {
                            return executeSandboxedCode(value, code);
                        }else if(typeof value === "object"){
                            // let keys = [];
                            // if(params && params.functionType && params.functionType.arguments){
                            //   keys = params.functionType.arguments.map((o) => `${o.title}: any`);
                            // }
                            return () => {};
                        }
                        break;
                    }else {
                        if(typeof value === "object"){
                            if(config.run.utils[funName]){
                                if(!code[funName]) code[funName] = config.run.utils[funName]();
                                return code[funName](value);
                            }
                        }
                    }
                }
        }
        return value;
    }

    /**
     * @name 根据module 返回组件 Props参数
     * @param key 组件id
     * @param value 
     * @param code 函数组件是依赖的环境变量
     * @returns 
     */
    getModuleProps = (key: string, value: any, code: Store) => {
        // console.log('getModuleProps', key, props);
        const item = this.elements.get(key);
        let data = value;
        // if(item.props){ 这种方式需要循环遍历props 消耗太大，暂时取消这种方式
        //     data = this.deepPropsSchema(value, item?.props)
        // }
        if(item.specialPaths.length){
            // 根据实现解析出来需要替换的变量路径specialPaths，对prpos 参数进行整改
            // console.log('specialPaths', item.key, item.specialPaths)
            const recursionList = (item: SpecialItem, parentPath: string[] = []) => {
                const paths = [...parentPath, ...item.paths];
                const value = safeGet(data, [...parentPath, ...item.paths]);
                if(!value) return;
                if(item.child && item.child.length){
                    if(Array.isArray(value)){
                        const length = value.length;
                        item.child.forEach((o) => {
                            for(let i=0; i< length; i++){
                                recursionList(o, [...paths, i.toString()]);
                            }
                        })
                    }
                }else {
                    safeSet(data, paths, this.getPropsValue(value, item.format as any, code, item.params));
                }
            }
            item.specialPaths.forEach((o) => recursionList(o))
        }else if(item.source === moduleSource.html){
            for (const vKey in value) {
                // 这边要对首层数据进行判断, 有可能为html中默认函数
                if(typeof data[vKey] === "string" && isBuilderFun(data[vKey]) && eventkeys.includes(vKey)){
                    safeSet(data, [vKey], this.getPropsValue(data[vKey], 'function', code));
                }
            }
        }
        // console.log('data', data)
        return data;
    }


}

export default new ModuleStore();

