import { ConfigProps } from "./interface";

/**
 * 这个文件全局配置会抛出给客户使用
 */
const config:ConfigProps = {
    parse: false,
    parseConfig: {
        saveCustomModule: async () => {}
    },
    modules: {
        getRender: async () => () => null,
        getIcon: (value: string) => "NOT ICON",
    },
    api: {
        getModuleList: async () => null,
    },
    schema: {
        formats: {},
        // 数据源
        sources: {},
        pageInjectedVars: [],
    },
    lessURL: "https://cdn.bootcdn.net/ajax/libs/less.js/4.2.0/less.min.js",
    typescriptURL: "https://cdn.bootcdn.net/ajax/libs/typescript/5.2.2/typescript.min.js",
    dependencies: {
        arco: "@arco-design/web-react",
    },
    importlibrarys: {},
    run: {} as any,
}


export const defineConfig = (obj: Partial<ConfigProps>) => {
    for (const key in obj) {
        if(typeof config[key] === "object"){
            Object.assign(config[key], obj[key]);
        }else {
            config[key] = obj[key];
        }
    }
}

export default config;