/**
 * 路径逆向解析 例如 [data, 0, name]
 * 返回 data[0].name
 */
export const getArrayToStringPath = (parts: string[]) => {
  const combinedPath = parts.reduce((path, part) => {
    if (!isNaN(Number(part))) {
      return `${path}[${part}]`;
    } else {
      return `${path}.${part}`;
    }
  })
  return combinedPath;
}


/**
 * 路径解析，将路径解析为数组路径， 例如 data[0].name
 * 返回 [data, 0, name]
 */
const getStringPathToArray = (path: string) => {
  const sanitizedPath = path.replace(/\['?/g, '.').replace(/'?\]/g, ''); // 将[' 替换为 .，将 '] 替换为空字符串
  return sanitizedPath.split('.').filter((o) => /^[$a-zA-Z_0-9()]+$/.test(o));
}

/**
 * 解析jsx 结构，返回解析后的变量结构
 */
const parsingStringVarToObject= (consts: string[], key: any) => {
  const obj: any = {
    i18next: {
      t: (str: string) => `$t{ ${str} }`
    },
    config: {},
    utils: {

    },
    store: {}
  };
  for (const key in config.schema.sources) {
    const { funName, type } = config.schema.sources[key];
    // obj.utils[funName] = (o) => o;
    if(type === "function"){
      obj.store[funName] = (fun) => {
        return (new Function(
          `{${Object.keys(obj).join(',')}}`,
          "return "+fun.toString().split('=>')[1])
        )(obj)
      }
    }else {
      obj.store[funName] = (o) => o;
    }
  }
  for (const path of consts) {
    const names = getStringPathToArray(path);
    if(
      names.length && 
      // 特殊变量，已经在组件中定义
      !['console', 'i18next'].includes(names[0]) &&
      // 必须符合变量命名规则
      isValidVariableName(names[0])
    ){
      // console.log('path', path, names )
      if(names[names.length - 1].endsWith('()')){
        // 最后一个为函数
        const funName = names.pop().slice(0, -2);
        _.set(obj, names, {
          ..._.get(obj, names, {}),
          [funName]: () => {
            return `\${ \`${names.join('`.`')}\`.${funName}() }`
          }
        })
      }else {
        _.set(obj, names, {
          ..._.get(obj, names, {}),
          [key]: `\${ \`${names.join('`.`')}\` }`
        })
      }
    }
  }

  // 对对象进行处理
  function processObject(objs, paths=[]) {
    const keys = Object.keys(objs);
    if (keys.length === 0 && objs[key]) {
      _.set(obj, paths, objs[key]);
    }else {
      for (const objKey in objs) {
        if(objKey != key && typeof objs[objKey] === "object"){
          processObject(objs[objKey], [...paths, objKey]);
        }
      }
    }
  }
  processObject(obj);
  return obj;
}

/**
 * 根据jsx 结构变量，转化为真实props
 */
const varToObjectToProps = (props: any, key: any) => {
  // 定义object值
  const recursionObject = (obj: any, paths: string[]) => {
    if(typeof obj === 'object'){
      if(obj[key]){
        _.set(props, paths, obj[key])
      }else {
        for (const path in obj) {
          const value = obj[path];
          if(value){
            if(typeof value === 'object'){
              recursionObject(value, [...paths, path]);
            }else if(typeof value === "function"){
              _.set(props, [...paths, path], `(${value.toString()})`)
            }
          }
        }
      }
    }
  }
  recursionObject(props, []);
  return props;
}

