/**
 * @title jsx 文本解析
 * @param params 所有用到的参数列表（jsx）
 * @param result imports 导入变量合集
 * @param jsxStr jsx文本
 */
const getJsxData = (params: string[], result: ElementList[], jsxStr): pageDataProps['list'] => {
  const symbokKey = Symbol("Count");
  const varObject = parsingStringVarToObject(params, symbokKey);
  // 删除重复定义
  for (const item of result) {
    if(varObject[item.name]) delete varObject[item.name];
  }
  const varNames = Object.keys(varObject).join(',');
  const createComponent = new Function(`React, {${varNames}}`, `
      const Fragment = React.Fragment;
      const Page = (props) => "page";
      const For = () => "basics_for";
      const If = () => "basics_if";
      ${result.map((o) => {
        let str = `const ${o.name} = (props) => "${o.id}";`;
        if(o.items && o.items.length) {
          for (const item of o.items) {
            str += `${o.name}.${item.name} = (props) => "${item.id}";`;
          }
        }
        return str;
      }).join('\n')}
  
      return ${jsxStr}
    `
  );
  // console.log('elements', result, moduleStore.elements)
  const pageData = createComponent(
    {
      createElement: (getId, props, ...children) => {
        const item: any = {
          id: getUuid("hash"),
          key: typeof getId === "function"? getId() : getId,
          name: "", // 组件名称
          // props: { ...props },
          props: props? varToObjectToProps(props, symbokKey) : {},
          children: []
        }
        
        const childrenList = children.reduce((arr: any[], item) => {
          if(Array.isArray(item)) return arr.concat(item);
          return [...arr, item];
        },[]).filter((o) => o).map((o) => {
          if(typeof o === "object" && o[symbokKey]){
              return { id: getUuid('hash'), key: 'basics_text', nickname: "文本",  props: { value: o[symbokKey] } }
          }else if(typeof o !== "object"){
            return { id: getUuid('hash'), key: 'basics_text', nickname: "文本",  props: { value: o } }
          }else {
            return o;
          }
        })
        // console.log('createElement', item.key, JSON.parse(JSON.stringify(item)), children);
        if(item.key === "basics_for"){
          const isFunctionNode = item.props.isFunctionNode;
          const { params = [], ofName, countList } = item.props.data as functionNodeType
          item.props = {
            countList
          }
          if(isFunctionNode){
            Object.assign(item.props, {
              params,
              list: childrenList
            })
            return { [symbokKey]: item.props };
          }else {
            Object.assign(item.props, {
              of: ofName? `\${ ${ofName} }` : "",
              each: params[0],
              index: params[1],
            })
          }
        }
        const element = moduleStore.elements.get(item.key);
        if(element){
          item.name = element.name;
          item.nickname = element.nickname;
          const properties = element.props?.properties;
          if(properties && properties.children){
            if(properties.children.format === 'node'){
              // 弹窗组件（例如 Modal)，children 是通过node 参数配置，需要将children 存入props 中
              item.props.children = childrenList;
              return item;
            }else if(properties.children.format === "functionNode"){
              if(children.length == 1 
                && children[0][symbokKey] 
                && typeof children[0][symbokKey] === "object"
              ){
                // 判断是否为function Node 参数格式类型，如果是则进行参数转换
                const { list, ...childProps } = children[0][symbokKey];
                item.props.children = childProps;
                item.children = list; 
              }
            }
          }
        }
        if(['basics_if', 'basics_for'].includes(item.key)){
          // console.log('childrenList', childrenList);
          item.children = childrenList.map((o) => ({ ...o, parentId: item.id }));
          return item;
        }
        if(item.key == "Fragment") return childrenList.length? childrenList : null;
        if(children.length === 1 && typeof children[0] != "object"){
          // console.log('item.props.children', item.props, children)
          item.props.children = children[0];
        }else if(children.length === 1  && typeof children[0] == "object" && children[0][symbokKey] ){
          item.props.children = children[0][symbokKey];
        }else {
          item.children = childrenList.map((o) => ({ ...o, parentId: item.id }));
        }
        return item
      },
      Fragment: (...arg) => "Fragment"
    },
    varObject,
  )

  // console.log('pageData', pageData)
  return treeToFlatten(Array.isArray(pageData)? pageData : [pageData]);
}

/**
 * 将jsx 转为可执行list
 */
export const JsxToPageList = async (data: TypeData, page: pageDataProps) => {
  // 依赖反序列化
  const dependsReverse = Object.keys(depends).reduce((obj, key) => ({ ...obj, [depends[key]]: key }), {});
  const {
    jsxBody, imports, exports, interfaces, params = [], useMemos,
    refFunction, defaultProps, initialProps, useEffects
  } = data;
  const { props, refProps } = getInterfaceSchema(interfaces);
  delete props?.properties?.forwardRef; // 删除forwardRef 注入参数
  const store: any = {
    page: {
      props,
      useMemos: [],
      useEffects: getEffectsData(useEffects)
    } as pageDataProps['page'],
    importlibrarys: {},
    data: null,
    isRef: false,
    refFunction,
    refProps
  };
  if(defaultProps) store.defaultProps = eval(`(${defaultProps})`);
  if(initialProps) store.initialProps = eval(`(${initialProps})`);
  try{
    if(Array.isArray(imports)){
      const result: ElementList[] = [];
      const elements = Array.from(moduleStore.elements.values());
      const sourceMap = { 
        [moduleSource.custom]: true,
        [moduleSource.context]: true,
        // [moduleSource.system]: true,
      };
      const elMap = new Map(elements.filter((o) => {
        return sourceMap[o.source];
      }).map((o) => [o.name, o]));
      if(exports && exports.hocs){
        for (const hoc of exports.hocs) {
          if(hoc.name == "observer"){
            const [IndexName, params] = hoc.params;
            try{
              const result = Function(`return ${params}`)()
              if(result.forwardRef) store.isRef = true;
            }catch{

            }
          }
        }
      }
      // 为避免map 存在重名的情况，所以 system 组件单独创建map
      const systemMap = new Map(elements.filter((o) => {
        return o.source == 'system' || o.source == '@system/schema';
      }).map((o) => [o.name, o]));
      // console.log('imports', imports)
      for (const item of imports) {
        const { modules, from, default: defaultName } = item;
        const originName = from.replace(/\'/g, "");
        if(originName.indexOf('@/components') !== -1){
          // 自定义组件
          const el = elMap.get(defaultName);
          if(el){
            result.push({
              id: el.key,
              name: el.name,
            })
          }
        }else if(originName.indexOf('@/context') !== -1){
          // context 内容
          const el = elMap.get(defaultName);
          if(el){
            result.push({
              id: el.key, name: el.name, 
              items: [{ id: el.key, name: `Provider` }]
            })
          }
        }else {
          if(dependsReverse[originName]){
            // 确保组件资源存在
            if(Array.isArray(modules)){
              for (const module of modules) {
                // 根据文件名称确认组件唯一id
                // console.log('module', module)
                result.push({
                  id: convertToSnakeCase(`${dependsReverse[originName]}${module.name}`),
                  name: module.alias || module.name,
                  // 这边后期可以考虑优化，通过预设items 值，减少加载时间
                  items: elements.filter((o) => o.name.indexOf(module.name + '.') !== -1).map((o) => {
                    return {
                      id: o.key,
                      name: o.name.slice(module.name.length + 1),
                    }
                  })
                })
              }
            }
          }else if(config.importlibrarys[originName]){
            store.importlibrarys[originName] = {
              defaultName: originName,
              list: modules
            }
          }else if(originName === "@system/schema"){
            for (const item of modules) {
              const el = systemMap.get(item.name);
              if(el){
                result.push({
                  id: el.key,
                  name: el.name, 
                })
              }
            }
          }else if(originName.indexOf('@system') !== -1){
            // console.log('AsyncButton', originName, defaultName, systemMap)
            const el = systemMap.get(defaultName);
            if(el){
              result.push({
                id: el.key,
                name: el.name, 
              })
            }
          }
        }
      }
      if(useMemos){
        store.page.useMemos = useMemos.map((o) => {
          const item = getUseMemosData(o);
          if(o.isFunctionNode){
            // console.log('jsxBody', o.jsxBody.outputText)
            const list = getJsxData(o.params, result, o.jsxBody.outputText);
            _.assign(item, {
              isFunctionNode: true,
              functionNode: {
                countList: o.countList,
                // 解析jsx 节点
                list: list,
                jsxBody: getPageJsxBody(list)
              }
            } as memoItem)
          }

          return item;
        })
      }
      if(jsxBody){
        store.data = getJsxData(params, result, jsxBody.outputText);
        console.log('pageData', store.data, store)
        return store;
      }
    }
  }catch(e){
    throw e;
    // console.error(e);
  }
}


/**
 * 将store 文本转为可执行data
 */
export const storeToPageData = async (data: TypeData, page: pageDataProps) => {
  const { classes, interfaces } = data;

  const { vars, constructorStr, gets, methods } = classes;


  const pageData: pageDataProps['page'] = {
    vars: vars.map((o) => {
      return {
        name: o.name,
        type: o.type,
        value: jsVarToRuleVar(o.block),
        description: o.comment,
      }
    }).filter((o) => {
      // 过滤掉不符合命名规则变量
      return new RegExp(Pattern.namespace).test(o.name);
    }),
    constructorStr,
    methods: methods.map((o) => ({
      name: o.name,
      value: o.block,
      description: o.comment,
    })),
    computeds: gets.map((o) => ({
      name: o.name,
      type: o.type,
      value: o.block,
      description: o.comment,
    }))
  }

  // console.log('pageData', pageData, dataSchema);
  return pageData;
}


