import React, { ReactNode, useContext, useEffect, useMemo, useState } from "react";;
import { FormInstance, Form, Button, TableColumnProps, TableProps, Space, Tooltip, Popover, Drawer, Modal, Grid, FormProps } from "@arco-design/web-react";
import { FormItem } from "../interface";
import { IconDown, IconEdit, IconMindMapping, IconMinus, IconPlus, IconRight, IconSettings, IconSort } from "@arco-design/web-react/icon";
import _ from 'lodash';
import { generateFormListKeys } from "src/utils/form";
import Context from "../context";
import { getUuid } from "src/utils";
import { FormListField } from "src/types/form";
import TableFixed from "src/components/custom/ProTable/TableFixed";
import Store from './store';
import DorpTree, { DorpTreeProps } from "src/components/custom/DorpTree";
import { observer } from "mobx-react-lite";


interface renderExtraParam {
    form: FormProps['form'];
    field: string;
    store: Store;
    list: any[];
}
export interface TableEditorProps {
    form?: FormInstance;
    field?: string;
    item?: FormItem;
    // widgets?: FormGenerateItem['widgets'];
    renderFormItemList?: any;
    // 
    renderExtra?: (param: renderExtraParam) => ReactNode;
    defaultLength?: number;
}

const TableEditor = ({ 
    item, form: pform, field,
    renderFormItemList, renderExtra,
    defaultLength = 4,
}: TableEditorProps) => {
    const context = useContext(Context);
    const [store] = useState(() => new Store());
    const form = context.form || pform;

    useState(() => {
        store.form = form;
        store.field = field;
        store.item = item;
        store.renderFormItemList = renderFormItemList;
        store.init();
    })

    const {
        fields, setFields, remove, addItem,
        formList, list,
    } = store;

    const extraRender = useMemo(() => {
        if(renderExtra){
            return renderExtra({ form, field, store, list });
        }
        return null;
    },[])

    const add = () => {
        setFields([ ...fields, { key: getUuid(), field: field }])
        const innerSetFieldValue = form.getInnerMethods(true).innerSetFieldValue;
        var value = form.getFieldValue(field) || [];
        value[value.length] = store.getItemDefaultValue;
        innerSetFieldValue(field, value);
    }

    const isChildren = useMemo(() => {
        return formList.find((o) => o.field === "children");
    },[])

    const [visible, setVisible] = useState<boolean>(false);
    const [treeData, setTreeData] = useState([]);
    const [treeColumn, setTreeColumn] = useState<DorpTreeProps['value']>([]);
    const [checkColumn, setCeckColumn] = useState<string[]>([]);
    const [expandedRowKeys, setExpandedRowKeys] = useState<(string | number)[]>([]);

    useEffect(() => {
        setTreeColumn(list.map((o) => {
            return {
                key: o.dataIndex,
                title: o.title,
            }
        }))
        setCeckColumn(list.slice(0,defaultLength).map((o) => o.dataIndex))
    },[list])

    const columns: TableProps['columns'] = useMemo(() => {
        const filterColumns = treeColumn.filter((o) => checkColumn.includes(o.key));
        const width = (() => {
            switch(filterColumns.length){
                case 1:
                case 2: return 380;
                case 3: return 280;
                case 4: return 200;
                default: return 170;
            }
        })()
        const map = new Map(list.map((o) => [o.dataIndex, { width: width, ...o }]));
        const result: TableProps['columns'] = filterColumns.map((o) => {
            return map.get(o.key) as any;
        })
        result.push({
            title: "操作",
            width: 100,
            cellStyle: {
                minWidth: 100,
            },
            render: (_, record, index) => {
                return (
                    <Space size="small">
                        <Button type="text" icon={<IconMinus />} 
                            onClick={() => {
                                remove(record, index)
                            }}
                        />
                        <Button type="text" icon={<IconPlus />}
                            onClick={() => {
                                addItem(record, index)
                            }}
                        />
                        <Button type="text" icon={<IconEdit />}
                            onClick={() => {
                                store.rowData = record;
                                store.rowIndex = index;
                                store.setVisible(true);
                            }}
                        ></Button>
                    </Space>
                )
            }
        })
        if(!isChildren) return result;

        return [
            {
                title: "",
                width: 60,
                className: "expand-icon",
                render: (_, record, index) => {
                    return (
                        <Button 
                            onClick={() => {
                                if(!record.children) record.children = [];
                                const key = getUuid();
                                record.children = [
                                    ...record.children,
                                    {
                                        field: `${record.field}[${index}].children`,
                                        key,
                                    }
                                ];
                                setFields([...fields])
                                setExpandedRowKeys([...expandedRowKeys, record.key])
                            }}
                            icon={<IconMindMapping />}
                        ></Button>
                    )
                }
            },
            ...result
        ]
    },[isChildren, treeColumn, checkColumn, list, fields, expandedRowKeys])

    const detailRender =  useMemo(() => {
        if(!store.visible) return null;
        if(!formList.length) return null;

        const result = formList.filter((o) => {
            return o.field !== "children";
        }).map((o) => {
            return {
                colSpan: 12,
                ...o,
                field: `${store.rowData.field}[${store.rowIndex}].${o.field}`,
            }
        })
        return renderFormItemList(result);
    },[store.visible])

    // const getTableTitle = () => <div >1111</div>

    return (
        <div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <Button
                    type="primary"
                    onClick={() => {
                       add()
                    }}
                >Add</Button>
                <Space>
                    {extraRender}
                    <Tooltip content="顺序设置">
                        <Button type="primary" icon={<IconSort />} 
                            onClick={() => {
                                form.validate().then(() => {
                                    const res = form.getFields();
                                    const titleKey = list[0].dataIndex;
                                    const fieldKey = list[1]? list[1].dataIndex : "";
                                    const loop = (list: FormListField[]) => {
                                        return list.map((o,i) => {
                                            const itemKey = `${o.field}[${i}]`;
                                            const option = _.get(res, itemKey, {});
                                            const item: any = {
                                                key: o.key,
                                                record: option,
                                                title: option[titleKey],
                                            }
                                            if(o.children){
                                                item.children = loop(o.children);
                                            }
                                            if(fieldKey && option[fieldKey] && typeof option[fieldKey] === "string"){
                                                item.title = `${item.title}(${option[fieldKey]})`;
                                            }
                                            return item;
                                        })
                                    }
                                    const result = loop(fields)
                                    setTreeData(result);
                                    setVisible(true);
                                })
                            }}
                        />
                    </Tooltip>
                    <Popover
                        title="展开字段"
                        triggerProps={{ trigger: "click" }}
                        position='br'
                        content={(
                            <DorpTree
                                style={{ width: 200, maxHeight: 300, overflowY: "auto" }}
                                isSingle
                                checkable
                                value={treeColumn}
                                checkedKeys={checkColumn}
                                onCheck={setCeckColumn}
                                onChange={setTreeColumn}
                            />
                        )}
                    >
                        <Tooltip content="列设置">
                            <Button type="primary" icon={<IconSettings />} />
                        </Tooltip>
                    </Popover>
                </Space>
            </div>
            <TableFixed
                className="form-generate-table-editor"
                columns={columns}
                data={fields}
                scroll={{
                    y: 350
                }}
                rowKey="key"
                pagination={false}
                expandedRowKeys={expandedRowKeys}
                onExpandedRowsChange={setExpandedRowKeys}
                expandProps={{
                    icon: ({ expanded, record, ...restProps }) =>
                      expanded ? (
                        <button {...restProps}>
                          <IconDown />
                        </button>
                      ) : (
                        <button {...restProps}>
                          <IconRight />
                        </button>
                      ),
                    
                }}
            />
            <Drawer
                visible={visible}
                onCancel={() => {
                    setVisible(false);
                }}
                title={`${item.label || ''}顺序调整`}
                placement="right"
                width={500}
                onOk={() => {
                    // 根据排序将组合最新list 数据
                    const loop = (list: any[]) => {
                        return list.map((o) => {
                            const item = o.record;
                            if(o.children){
                                item.children = loop(o.children);
                            }
                            return item;
                        })
                    }
                    const values = loop(treeData);
                    // 更新Form 表单
                    const innerSetFieldValue = form.getInnerMethods(true).innerSetFieldValue;
                    innerSetFieldValue(field, values);
                    // 更新fields 集合
                    const result = generateFormListKeys(values, field);
                    setFields(result)
                    setVisible(false)
                }}
            >
                <DorpTree
                    value={treeData}
                    isSingle={!isChildren}
                    onChange={setTreeData}
                />
            </Drawer>
            <Modal
                visible={store.visible}
                style={{
                    width: 800
                }}
                focusLock={false}
                footer={(a,b) => b}
                maskClosable
                onCancel={() => {
                    store.setVisible(false);
                }}
                onOk={() => {
                    store.setVisible(false);
                }}
                title="rowData"
            >
                <Grid.Row gutter={[16, 8]}>
                    {detailRender}
                </Grid.Row>
            </Modal>
        </div>
    )

}


export default observer(TableEditor);