import { moduleSource, modulePlatform, moduleTypes, moduleDisplay, TaroModuleSource, moduleDisplayType } from "src/types/module";
import { CSSProperties } from "react";
import { functionCountItem } from "src/types/code";


/**
 * 插入位置
 */
export enum insertPosition {
	// 上一个
	prev = 'prev',
	// 子类
	children = 'children',
	// 下一个
	next = 'next',
}

interface extraInfoProps {
	// 自定义组件用到的所有组件id 集合
	components?: string[];
	// 预览图片
	previewImg?: string;
	// lessStr 转为的css
	cssStr?: string;
	// data?: pageDataProps;
	// 是否将模块渲染在最外层
	portal?: boolean;
	// 是否允许事件
	isEvents?: boolean;
	// 模态组件
	isModal?: boolean;
	// dom 重绘
	isRepaint?: boolean;
	// 拖拽布局是否保留原有布局特性。 
	isOriginal?: boolean;
	// props 属性，默认参数值
	initialProps?: any;
	// 默认props( Index.defaultProps )
	defaultProps?: any;
	// 函数组件绑定是否需要绑定ref
	isRef?: boolean;
	// 定义res 类型
	refProps?: JSONSchema;
	// 定义res 绑定值
	refBody?: string;
	// useImperativeHandle
	useImperativeHandle?: any;
	className?: string;
	jsxRender?: string;
}
export interface ModuleItem {
	// 唯一ID
	uid?: string;
  	key: string;
	moduleId?: string;
	pluginId?: string;
	// 公共组件 ( 意外当前组件只是演示，无法修改 )
	isPublic?: boolean;
	// 模块名称
	name: string;
	// 模块昵称
	nickname?: string;
	// 模块图片
	imgUrl?: string;
	// 模块描述
	description?: string;
	// 模块类别
	category?: string;
	// 显示类型
	display?: moduleDisplayType;
	// 适用平台
	platform?: modulePlatform;
	// 模块价格
	price?: number;
	// 模块制造商
	manufacturer?: string;
	// 模块所需参数
	props?: JSONSchema;
	// 模块来源
	source?: string;
	// 模块额外信息
	extraInfo: extraInfoProps;
	// 自定义组建详细store 内容
	content?: pageDataProps
	// 组件生成的jsx 文本
	jsxRender?: string;
	// 更新时间（自定义组件更新）
	// updateAt?: number;
}

export interface ListItem {
	// 当前组件id(唯一)
	id: string;
	// 模块 key (对于数据表中 ID 字段)
	key?: string;
	// 模块名称( 英文 )
	name?: string;
	// 别名 (英文，name重复时要使用别名)
	aliasName?: string;
	// 模块昵称
	nickname?: string;
	// props 参数
	props?: any;
	// 排序
	sort?: number;
	// 父类组件id
	parentId?: string;
	// 相邻上一个节点id
	// prevId?: string;
	// 相邻下一个节点id
	// nextId?: string;
}

/**
 *     { dataIndex: 'name', title: '绑定字段' },
                            { dataIndex: 'default', title: '默认值' },
                            { dataIndex: 'description', title: '字段说明' },
 */
export interface QueryItem {
	// 参数字段名称
	name: string;
	// 字段默认值
	default: any;
	// 字段说明
	description: string;
}
interface MethodItem {
	// 事件名称
	name: string;
	// 事件内容(function)
	value: string;
	// 事件介绍
	description?: string;
}

interface computedItem {
	// 变量名称
	name: string;
	type: string;
	// 变量函数（需要返回内容）
	value: string;
	// 计算属性介绍
	description?: string;
}


// functionNode 配置
export interface functionNodeItem {
	funName: string;
	countList: functionCountItem[];
	description?: string;
	list?: ListItem[];
	params: JSONSchema[];
	jsxBody?: string;
}

interface watchItem {
	// 要监听的变量
	vars: string[];
	// 变量更改后要执行的函数
	data: string;
}

export interface effectItem {
	// 要监听的变量
	vars: string[];
	// 变量更改后要执行的函数
	value: string;
	// 描述
	description: string;
}

export interface memoItem {
	// 变量名称
	name: string;
	// 变量类型定义
	type: string;
	// 要监听的变量
	vars: string[];
	// 变量更改后要执行的函数
	value: string;
	// 描述
	description: string;
    // 判定为functionNode 类型
    isFunctionNode?: boolean;
	functionNode?: functionNodeItem;
}

interface contextItem {
	context: string;
	name: string;
}

interface varItem {
	name: string;
	type: string;
	value: any;
	description: string;
}

export interface pageProps {
	className?: string;
	style?: CSSProperties;
	// 页面输入参数
	query?: QueryItem[];
	// 组件props 属性
	props?: JSONSchema,
	// 页面data值
	data?: JSONSchema,
	// 模块变量参数值
	vars?: varItem[];
	// 组件事件列表
	methods?: MethodItem[];
	// constructor
	constructorStr?: string;
	// 计算属性
	computeds?: computedItem[];
	// 监听事件
	watch?: watchItem[];
	// useEffect hoc 列表
	useEffects?: effectItem[];
	// useMemo
	useMemos?: memoItem[];
	functionNode?: functionNodeItem
	// 元素列表
	elements?: functionNodeItem[];
	// 组件特有配置
	extraInfo?: ModuleItem['extraInfo'];
}

export interface moduleCssProps {
	// less 文件
	lessStr?: string;
	// less 编译后的css 文件
	cssStr?: string;
}

export interface pageDataProps {
	// 自定义组件所有用到的依赖
	components?: string[];
	lessStr?: string;
	cssStr?: string;
	page: pageProps;
	list: ListItem[];
}

/**
 * @name 针对functionNode 存储参数类型
 */
export interface FunctionNodeDataProps {
	params?: string[];
	countList?: functionCountItem[];
	list: ListItem[];
	jsxBody?: string;
}