interface DatabaseStoreConfig {
    // 更新的时候触发
    update: () => void;
}

/**
 * 全局数据源
 */
class DatabaseStore {
    config: DatabaseStoreConfig = { update: () => null };
    state: BaseStore[] = []
    /** 更新state */
    addState = (config: DatabaseStoreConfig, page: BaseStore) => {
        if(config) this.config = config;
        this.state.push(page);
    }

    /** 清空数据 */
    clear = () => {
        this.state = [];
    }

    loading = false;

    saveModules = () => {
        // console.log('loading', this.loading, this.state)
        if(this.loading) return;
        if(this.state.length){
            const list = this.state.filter((page) => {
                // 页面解析时，需要优先把页面去掉
                return page.isComponent && page.parse.isSave
            })
            if(list.length){
                this.loading = true;
                config.parseConfig.saveCustomModule(list).finally(() => {
                    this.config.update();
                    list.forEach((page) => {
                        page.parse.isSave = false;
                    })
                    this.loading = false;
                });
            }
        }
    }
}

export const database = new DatabaseStore();



interface PopoverFormProps {
    dom: HTMLElement;
    type: customType;
    onClose: () => void;
    value: any;
    onChange: (value: any) => void;
}

type customType = "icon" | "image";

const PopoverForm = ({
    dom, type, onClose, value, onChange
}: PopoverFormProps) => {

    const [input, setInput] = useState<string>(value);

    const divStyle = useMemo(() => {
        var range = document.createRange();
        range.selectNode(dom);
        // 获取元素的位置信息
        var rect = range.getBoundingClientRect();

        return {
            ..._.pick(rect, ['top', 'left', 'width', 'height']),
            position: "fixed",
            border: "rgb(var(--primary-6)) solid 1px",
            zIndex: 999
        } as React.CSSProperties
    },[])

    const updateChange = useCallback(delayedFunction((value) => {
        onChange(value);
    },800),[])
    
    const fieldProps: any = {
        valueType: type,
        value: input,
        onChange: (val) => {
            setInput(val);
            updateChange(val);
        }
    };

    return (
        <Popover
            trigger='hover'
            content={(
                <div style={{ width: 200 }}>
                    <Field {...fieldProps} />
                </div>
            )}
            onVisibleChange={(bool) => {
                if(!bool) onClose();
            }}
        >
            <div style={divStyle} ></div>
        </Popover>
    )
}


/**
 * 构建超级解析器具
 */
class Store {

    isSave: boolean = false;

    page: BaseStore;
    form: FormInstance;

    // 当前父级 Store;
    parent: Store;

    /**
     * 记录副作用值
     */
    effects = {

    }

    /**
     * 添加副作用
     */
    addEffect = (vm: string, fun: () => void) => {
        if(!vm) return;
        if(!this.effects[vm]) {
            this.effects[vm] = [];
        }
        this.effects[vm].push(fun);
    }

    /**
     * 清空副作用
     */
    clearEffect = () => {
        for (const key in this.effects) {
            this.effects[key].forEach((fun) => fun());
            delete this.effects[key];
        }
    }

    constructor({ store }: constructorProps){
        this.page = store;
    }


    /**
     * 移动时解析，为了优化运行体验，只在第一次进行解析
     */
    mouseHtml = (html: HTMLElement) => {
        // console.log('parseHtml', dataset, html.dataset)
        if(html.dataset['vm']){
            // 解析过的html 文件不在进行解析
            return;
        }
        // 标记当前html 文件，代表此文件已经解析过
        html.dataset.vm = getUuid('hash');
        // console.log('parseHtml', html, html.children, dataset);

        // this.parseHtml(html);
    }

    /**
     * 离开时解析，为了消除副作用，消除副作用的有影响
     */
    mouseoutHtml = (html: HTMLElement) => {
        // console.log('mouseoutHtml', html);
        const vm = html.dataset.vm;
        if(!vm){
            // 未标记文件，不做处理
            return;
        }
        // 处理当前副作用文件
        if(this.effects[vm]){
            // 消除副作用
            this.effects[vm].forEach((fun) => fun());
            delete this.effects[vm];
            // 对于存在副作用的dom 允许继续解析
            delete html.dataset.vm;
        }

        database.saveModules();
    }

    /** 节点解析初始化 */
    init = (html: HTMLElement) => {
        database.clear();
        this.parseHtml(html);
    }

    /** 页面解析初始化 */
    initPage = (html: HTMLElement, config: DatabaseStoreConfig) => {
        const parseHtmlStore = new ParseHTML();
        parseHtmlStore.parse = this;
        parseHtmlStore.page = this.page;
        parseHtmlStore.parsePage(config, this.page, html);

        return database;
    }


    /**
     * 解析html文件
     */
    parseHtml = (html: HTMLElement) => {
        const parseHtmlStore = new ParseHTML();
        parseHtmlStore.parse = this;
        parseHtmlStore.page = this.page;
        return parseHtmlStore.parseDOM(html);
    }
}


/**
 * 构建单例解析
 */
class ParseHTML{
    page: BaseStore;
    parse: Store;
    // 当前触发的html
    html: HTMLElement;

    /**
     * 获取元素props 参数
     */
    getModuleStore = (id: string) => {
        const mStore = this.page.mapStore.get(id);
        if(!mStore && this.parse.parent){
            return this.parse.parent.page.mapStore.get(id);
        }
        return mStore;
    }

    /**
     * html 可修改
        // const isSelected = this.page.selectId == id;
        // if(isSelected){
        //     form.setFieldValue('children', html.innerHTML)
        // }else {
        //     mapStore.setProps({
        //         ...props,
        //         children: html.innerHTML
        //     })
        // }
        // 更新文件信息
     */
    htmlEditChange = (html:HTMLElement, id: string, path: string[]) => {
        if(html.dataset.input) return;
        html.dataset.input = "1";  // 事件禁止重复添加
        // console.log('htmlEditChange', html, item, path);
        const mapStore = this.getModuleStore(id);
        // 目前只是支持纯文本编辑，如果存在文本和html文件需要额外解析，杂味完成
        html.setAttribute('contenteditable', "true");
        html.style.pointerEvents = "auto";
        const form = this.parse.form;
        html.addEventListener("input", action(() => {
            this.parse.isSave = true;
            _.set(mapStore.props, path, html.innerHTML);
            if(form && mapStore.id === this.page.selectId){
                form.setFieldsValue(toJS(mapStore.props));
            }
        }))
        html.addEventListener("click", (e) => {
            e.stopPropagation();
            e.preventDefault();
        })
        // html.addEventListener('dblclick', (e) => {
        //     e.stopPropagation();
        //     e.preventDefault();
        // })
    }

    /**
     * 绑定要修改的事件
     */
    addEventForm = (html: HTMLElement, id: string, path: string[], type: customType) => {
        if(html.dataset.click) return;
        html.dataset.click = "1";  // 事件禁止重复添加
        console.log('addEventForm', html, id);
        
        const mapStore = this.getModuleStore(id);
        const { props } = mapStore;
        html.style.cursor = "pointer";
        html.style.pointerEvents = "auto";
        const form = this.parse.form;
        html.addEventListener("click", (e) => {
            // console.log('mapStore', mapStore, path, item);
            const div = document.createElement('div');
            document.body.appendChild(div)
            ReactDOM.render(
                <PopoverForm
                    type={type}
                    value={_.get(props, path)}
                    onChange={action((value) => {
                        console.log('value', value)
                        this.parse.isSave = true;
                        _.set(mapStore.props, path, value);
                        if(form && mapStore.id === this.page.selectId){
                            form.setFieldsValue(toJS(mapStore.props));
                        }
                        switch(type){
                            case "icon":
                                if(value){
                                    // 渲染为 HTML 字符串
                                    let htmlString;
                                    try{
                                        htmlString = ReactDOMServer.renderToStaticMarkup(moduleStore.getIcon(value) as any);
                                    }catch(e){
                                        htmlString = ReactDOMServer.renderToStaticMarkup(moduleStore.getIcon(value) as any);
                                    }
                                    // 输出 HTML 字符串
                                    if(htmlString){
                                        // 创建一个临时容器
                                        const tempContainer = document.createElement('div');
                                        // 将 HTML 字符串赋值给容器的 innerHTML，从而创建 DOM 元素
                                        tempContainer.innerHTML = htmlString;
                                        // 获取容器中的第一个子元素，即你的 React 组件的根元素
                                        const domElement: any = tempContainer.firstChild;
                                        console.log('domElement', domElement, html);
                                        html.parentNode.replaceChild(domElement, html)
                                        html.remove();
                                        this.addEventForm(domElement, id, path, type);
                                    }
                                }else {
                                    html.remove();
                                }
                            break;
                            case "image":
                                html.setAttribute('src', value);
                            break;
                        }
                    })}
                    dom={html as any}
                    onClose={() => {
                        ReactDOM.unmountComponentAtNode(div);
                        document.body.removeChild(div);
                    }}
                />, 
                div
            );
            // ReactDOM.unmountComponentAtNode(div);
            e.stopPropagation();
            e.preventDefault();
        })
    }


    /**
     * html props 属性更新
     */
    htmlChange = (html: HTMLElement, id: string) => {
        // console.log('htmlChange', html, this.page)
        const tagName = html.tagName.toLowerCase();
        const mapStore = this.getModuleStore(id);
        const props = mapStore.props;

        let text = html.innerHTML;
        // console.log('html', html, html.children.length, html.children, toJS(props), toJS(mapStore.props))
        if(tagName == "img"){
            if(props.src === html.getAttribute('src')){
                this.addEventForm(html, id, ['src'], 'image');
            }
        } else if(html.children.length === 0){
            if(props.children && props.children == text){
                // 如果存在值且值是相等的
                this.htmlEditChange(html, id, ['children']);
            }
            // if(!props.children && !text) {
            //     // 空元素也可以编辑
            //     this.htmlEditChange(html, item, ['children']);
            // }
        } else {
            // 多元素，需要关闭 style
            html.style.pointerEvents = "none";
            if(html.getAttribute('contenteditable')){
                html.removeAttribute('contenteditable');
            }

            let first = html.firstChild; // 第一个节点对比
            // console.log('first', first, rects, range);

            if(first.nodeType === 3){
                // 确定为文本节点
                text = first.textContent;
                if(text && props.children && text === props.children){
                    // this.textEditChange(html, first, item, ['children']);
                    // 确保props 和 text 文件重合，可以进行编辑
                    var newSpan = document.createElement('span');
                    newSpan.innerHTML = first.textContent;
                    newSpan.dataset.vm = "1";
                    html.replaceChild(newSpan, first)
                    this.htmlEditChange(newSpan, id, ['children']);
                    // console.log('htmlEditChange', this.html, newSpan, item);
                    this.parse.addEffect(this.html.dataset.vm, () => {
                        first.textContent = newSpan.innerHTML;
                        if(html == newSpan.parentNode){
                            html.replaceChild(first, newSpan);
                        }
                        newSpan.remove();
                    })
                }
            }
        }
    }


    /**
     * 解析自定义组件
     */
    customChange = (html: HTMLElement, id: string) => {
        const store = this.getModuleStore(id);
        const element = moduleStore.elements.get(store.key);

        const page = new BaseStore({
            uid: store.key,
            isComponent: true,
            name: element.nickname || element.name,
        });

        page.setData(element.content);

        console.log(element.content, page);

        page.parse.parseHtml(html)
    }


    /**
     * 其他类型组件
     * 根据props 对应的schema 类型来解析定义对应组件
     */
    otherChange = (html: HTMLElement, id: string) => {
        // const schema = element.props;
        const mapStore = this.getModuleStore(id);
        const { props, propsData } = mapStore;
        // console.log('otherChange', html, html.children, props, mapStore)

        if(html.children.length){
            if(html.getAttribute('contenteditable')){
                html.removeAttribute('contenteditable');
            }
            // 获取内置组件html 中所哟文本信息
            const obj = {};
            const htmlObj: Record<string, HTMLElement> = {};
            const customObj: Record<string, customType> = {};
            const addObj = (key, html: HTMLElement, type?: customType) => {
                if(!key) return;
                obj[key] = (obj[key] || 0) + 1;
                htmlObj[key] = html;
                if(type){
                    customObj[key] = type;
                }
            }

            const hasMap = new Map(this.page.list.map((o) => [o.id, true]));
            /**
             * 遍历html 文件
             */
            const loop = (list: HTMLElement[]) => {
                for (const op of list) {
                    const dataset = getDataSet(op);
                    const id = dataset.u || dataset.v;
                    if(id && !hasMap.has(id)){
                        // 筛选出 functionNode 和 node 类型组件
                        this.parseList(id, op);
                    }
                    if(op.dataset.icon){
                        addObj(op.dataset.icon, op, "icon");
                    }else if(op.children.length){
                        loop(op.children as any);
                    }else if(op.innerHTML) {
                        addObj(op.innerHTML, op);
                    }
                }
            }
            loop(html.children as any);
            // 获取props 对应的参数，用于进行差值对比
            const objData = nonSwapObject(toJS(props));

            console.log('objData', html, objData, obj);
            Object.keys(obj).forEach((key) => {
                // 名称一直，无法判断要修改的属性，搁置
                if(obj[key] > 1) return;
                if(objData[key]){
                    if(customObj[key]){
                        // 非文本类型
                        this.addEventForm(htmlObj[key], id, objData[key], customObj[key]);
                    }else {
                        // props 中参数和内置组件文本对比通过，且是唯一值
                        this.htmlEditChange(htmlObj[key], id, objData[key]);
                    }
                }
            })

            // console.log('html', html, objData, obj, customObj);
        }else {
            if(props.children == html.innerHTML){
                this.htmlEditChange(html, id, ['children']);
            }
        }
    }

    /**
     * 解析组件
     */
    parseList = (id: string, html: HTMLElement) => {
        const store = this.getModuleStore(id);
        if(!store) return;
        console.log('parseList', id, store.props, html)
        const key = store.key;
        const element = moduleStore.elements.get(store.key);
        // const form = this.page.settingStore.form;
        const { source, name } = element;

        // console.log('elememnt', source, element)

        switch(source){
            case "html":
                this.htmlChange(html, id);
            break;
            case "custom":
                this.customChange(html, id);
            break;
            default:
                this.otherChange(html, id);
        }
    }

    
    /**
     * 获取list 信息，同步了props 参数
     */
    setDataList = (page: BaseStore, list: ListItem[]) => {
        return list.map((o) => {
            page.addMapStore(o.id, { props: o.props, key: o.key })
            const element = moduleStore.elements.get(o.key);
            const option = {
                ...o,
                props: toJS(o.props)
            }
            if(element.specialPaths.length){
                // 根据实现解析出来需要替换的变量路径specialPaths，对prpos 参数进行整改
                // console.log('specialPaths', item.key, item.specialPaths)
                const recursionList = (item: SpecialItem, parentPath: string[] = []) => {
                    const paths = [...parentPath, ...item.paths];
                    const value = _.get(option.props, [...parentPath, ...item.paths]);
                    if(!value) return;
                    if(item.child && item.child.length){
                        if(Array.isArray(value)){
                            const length = value.length;
                            item.child.forEach((o) => {
                                for(let i=0; i< length; i++){
                                    recursionList(o, [...paths, i.toString()]);
                                }
                            })
                        }
                    }else {
                    if(item.format === "node"){
                        if(value && typeof value == "object"){
                            const values = Array.isArray(value)? value : [value];
                            this.setDataList(page,treeToFlatten(values))
                        }
                    }else if(item.format === "functionNode"){
                        if(value && typeof value == "object"){
                            const { params, list} = value as FunctionNodeDataProps;
                            this.setDataList(page, list)
                        }
                    }
                    }
                }
                element.specialPaths.forEach((o) => recursionList(o))
            }
        })
    }
       

    parsePage = (config: DatabaseStoreConfig, page: BaseStore, html: HTMLElement) => {
        this.setDataList(page, page.list)

        const dataset = getDataSet(html);
        const { parse } = page;
        parse.parent = this.parse;

        database.addState(config, page);
        if(dataset.v){
            // 当前自定义组件节点解析
            const parseHtmlStore = new ParseHTML();
            parseHtmlStore.parse = parse;
            parseHtmlStore.page = this.page;
            parseHtmlStore.parseList(dataset.v, html);
        }

        // 循环遍历dom 结点
        const loop = (list: HTMLElement[]) => {
            for (const item of list) {
                const domList = parse.parseHtml(item);
                if(domList){
                    // 自定义组件一次性解析页面所有节点，发现节点继续解析
                    loop(domList);
                }
            }
        }
        // 解析子节点
        loop([html])
        // page.parse.parseHtml(html.parentNode as any);
    }


    /**
     * 解析自定义组件
     */
    parseCustom = (id: string, html: HTMLElement) => {
        const store = this.getModuleStore(id);
        if(!store) return;
        // 深度遍历-props 参数更新
        this.otherChange(html, id);
        const element = moduleStore.elements.get(store.key);
        // const form = this.page.settingStore.form;
        const { source, nickname, name, content } = element;
        const page = new BaseStore({
            uid: store.key,
            isComponent: true,
            name: nickname || name,
        });
        page.setData(content);
        this.parsePage({ update: store.updatePropsKey },page, html);
    }



    parseDOM = (html: HTMLElement) => {
        // console.log('parseDOM', html)
        this.html = html;
        let doms = [];
        const loop = (list: HTMLElement[]) => {
            if(!list.length) return;
            const result: HTMLElement[] = list as any;
            for (const item of result) {
                const dataset = getDataSet(item);
                if(dataset.u){
                    this.parseCustom(dataset.u, item);
                    doms.push(item);
                }else if(dataset.v){
                    // 解析到了当前组件类型
                    this.parseList(dataset.v, item)
                    doms.push(item);
                }else {
                    // 未找到组件，轮询查找
                    loop(item.children as any);
                }
                // console.log('parseHtml-item', item, item.children, dataset);
            }
        }
        loop(html.children as any);
        return doms;
    }
}

export default Store;