import React, { useContext, useState } from 'react';
import {
  DatePicker,
  FormInstance,
  Input,
  InputNumber,
  InputTag,
  Select,
  Switch,
  Radio,
  TimePicker,
} from '@arco-design/web-react';
import { FormItem } from '../interface';
import { formFields } from 'src/types/schema';
import EditUnion from 'src/components/custom/EidtUnion';
import EditRefSchema from 'src/components/custom/EidtRefSchema';

import config from 'src/config';


interface FieldProps {
  field?: string;
  value?: any;
  onChange?: (value: any) => void;
  valueType?: FormItem['valueType'];
  fieldProps?: any;
  preValueChange: FormItem['preValueChange'];
  form: FormInstance;
}
const Field = ({
  field,
  valueType = formFields.input,
  fieldProps = {},
  preValueChange,
  form,
  ...props
}: FieldProps) => {

  const onChange = async (val: any, ...arr: any[]) => {
    let value = val;
    if (preValueChange) {
      if (preValueChange instanceof Promise) {
        value = await preValueChange(val, form, ...arr);
      } else {
        value = preValueChange(val, form, ...arr);
      }
    }
    // props.onChange 来源 Form.Item
    if (props.onChange) props.onChange(value);
    // 此处onChange事件，来源组件Props
    if (fieldProps.onChange) fieldProps.onChange(value);
  };

  console.log('valueType', valueType);

  if(config.schema.formats[valueType]){
    const Element: any = config.schema.formats[valueType];
    return <Element {...fieldProps} {...props} onChange={onChange} />
  }
  switch (valueType) {
    case formFields.input:
      return (
        <Input
          placeholder="请输入"
          autoComplete="off"
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      );
    case formFields.inputTag:
      return (
        <InputTag  
          placeholder="请输入"
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      )
    break;
    case formFields.text:
      return (
        <Input.TextArea 
          placeholder="请输入"
          autoComplete="off"
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      )
    case formFields.password:
      return (
        <Input.Password 
          placeholder="请输入"
          autoComplete="off"
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      )
    case formFields.date: 
        return (
          <DatePicker
            placeholder="请选择"
            {...fieldProps}
            {...props}
            onChange={onChange}
          />
        );
    case formFields.dateRange:
      return (
        <DatePicker.RangePicker 
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      )
    case formFields.time: 
        return (
          <TimePicker
            placeholder="请选择"
            {...fieldProps}
            {...props}
            onChange={onChange}
          />
        );
    case formFields.timeRange:
      return (
        <TimePicker.RangePicker 
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      )
    case formFields.inputNumber:
      return (
        <InputNumber
          placeholder="请输入"
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      );
    case formFields.select:
      // console.log('formFields.select', fieldProps, props)
      return (
        <Select
          placeholder="请选择"
          allowClear
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      );
    case formFields.radio:
      return (
        <Radio.Group
          {...fieldProps}
          {...props}
        >
        </Radio.Group>
      )
    case formFields.radioButton:
      return (
        <Radio.Group
          type="button"
          {...fieldProps}
          {...props}
        >
        </Radio.Group>
      )
    case formFields.switch:
      return (
        <Switch
          checked={props.value}
          {...fieldProps}
          {...props}
          onChange={onChange}
        />
      );
    case formFields.union:
      return (
        <EditUnion {...fieldProps} {...props} onChange={onChange} />
      )
    case formFields.refSchema:
      return (
        <EditRefSchema
          {...fieldProps} {...props}
          parentKey={field}
          form={form}
          onChange={onChange}
        />
      )
    default:
      return null;
  }

};

export default Field;
