import { Alert } from "@arco-design/web-react";
import React from "react";

class MyErrorBoundary extends React.Component<any, any> {
    constructor(props) {
      super(props);
      this.state = { 
        hasError: false,
        errMsg: '',
      };
    }
    timer: any;
  
    componentDidCatch(error, info) {
      if(!this.state.hasError && !this.timer){
        this.timer = setTimeout(() => {
          this.timer = null;
          this.setState({ 
            hasError: false
          })
        },6000)
      }
      this.setState({ hasError: true, errMsg: error.message });
      // console.log("error-children", this.props.children);
    }

    componentWillUnmount(): void {
        if(this.timer) clearTimeout(this.timer);
    }
  
    render() {
      const { errMsg } = this.state;
      const { alert } = this.props;
      if (this.state.hasError) {
        return (
          <div data-id={this.props.id}>
            <Alert type="error" content={alert || `发生了错误~`} />
            <code style={{ color:"red" }}>
              {errMsg}
            </code>
          </div>
        )
      }
      return this.props.children;
    }
}

export default MyErrorBoundary;