import React, { HTMLProps, useRef } from 'react';
import { useDrag } from 'react-dnd';
import styles from './index.module.less';
const type = 'template';

interface DragViewProps extends HTMLProps<HTMLDivElement> {
  // 数据源
  data: any;
}
export default ({ data, ...props }: DragViewProps) => {
  const ref = useRef(null);

  const [, drag] = useDrag({
    type,
    item: data,
    canDrag: (monitor) => {
      // addElement(true);
      return true;
    },
    end: () => {
      // addElement(false)
    },
  });
  drag(ref);

  return (
    <div ref={ref} className={`${styles.listContent || ''}`} {...props}>
      <div style={{ pointerEvents: 'none' }}>{props.children}</div>
    </div>
  );
};
