import { InterfaceItem, properItem, TypeFlags, SyntaxKind, ObjectFlags } from "src/types/transform";
import _ from 'lodash';

class TransformStore {

    interNode = {

    }
}


const getText = (text: string, o: properItem) => {
    const value = text.replace(/\"/g, '');
    const { jsDocs } = o;
    if(jsDocs && jsDocs[0]){
        const { tags } = jsDocs[0];
        if(tags && value){
            const key = `enum-${value}`;
            if(tags[key]) return { value, label: tags[key] }
        }
    }
    return value;
}

/**
 * 根据jsDoc 设置schema数据
 */
export const setSchemaJsDocs = (schema: JSONSchema, jsDocs: properItem['jsDocs']) => {
    if(!Array.isArray(jsDocs)) return;

    const setDocsVars = (data: JSONSchema, prefix: string = "") => {
        if(jsDocs[0]){
            const { tags = {}, comment } = jsDocs[0];
            [   
                'default', 
                'title', 
                'category', 
                'pattern', 
                'format',
                'listType',
                'widget',
                'show',
                'fieldProps',
                'formItemProps', 
                'colProps',
                'formGenerateProps',
                'columnProps',
            ].forEach((key) => {
                const filedKey = `${prefix}${key}`;
                if(tags[filedKey]){
                    try{
                        data[key] = JSON.parse(tags[filedKey]);
                    }catch(e){
                        data[key] = tags[filedKey];
                    }
                    delete tags[filedKey]
                }
            })
        }
    }
    const { type, anyOf, items } = schema;
    // 默认参数
    setDocsVars(schema);
    if(anyOf && Array.isArray(anyOf)){
        anyOf.forEach((o,i) => {
            setDocsVars(o,`anyOf${i}-`);
        })
    }else if(type == "array" && !Array.isArray(items)){
        setDocsVars(items, `items-`)
    }
    if(jsDocs.length){
        const { tags, comment } = jsDocs[0];
        schema.description = tags['zh'] || comment;
    }
}


export const properToSchema = (proper: properItem ): JSONSchema => {
    if(!proper) return {};
    const {  kind, flag, objFlag, text, children = [], jsDocs, properties, returnType } = proper;
    const schema: JSONSchema = {
    };
    if(proper.name == "className"){
        // schema.type = ["string", "array"]
        schema.type = "string";
        schema.format = "class";
        return schema;
    }
    const { name } = properties || {}; 
    switch(kind){
        // (() => any)
        // nodejs 中对ParenthesizedType 类型进行处理 跳过中对ParenthesizedType处理
        // case SyntaxKind.ParenthesizedType:
        case SyntaxKind.FunctionType:  // 函数类型 () => {}
            schema.type = "string";
            const returnSchema = properToSchema(returnType);
            schema.format = "function";
            if(returnSchema && returnSchema.format === "node"){
                schema.format = "functionNode";
            }
            schema.functionType = {
                // 函数参数声明
                arguments: children.map((o) => {
                    return {
                        ...properToSchema(o),
                        title: o.name,
                    }
                }),
                // 返回参数约束
                return: returnSchema,
            }
        break;
        case SyntaxKind.TypeReference: // 连接类型
        case SyntaxKind.IndexSignature:
            switch(text.trim()){
                case 'CSSProperties':
                    schema.type = "object";
                    schema.format = "style";
                break;
                case "ReactNode":
                case "React.ReactNode":
                    schema.type = "array";
                    schema.format = "node";
                break;
                case "Array":
                    schema.type = "array";
                    if(properties.children){
                        schema.items = properToSchema(properties.children[0]);   
                    }
                break;
                default:
                    if(
                        objFlag != ObjectFlags.Interface  // Interface 为接口类型
                        && TypeFlags.Object && properties 
                        && Object.keys(properties).length
                    ){
                        schema.type = "array";
                        if(properties.children && properties.children[0]){
                            schema.items = properToSchema(properties.children[0]);
                        }
                    }else {
                        let refName = name || text;
                        refName = refName.endsWith('Props')? refName.slice(0,-5) : refName;
                        // _.set(schema,['extraInfo', 'reference'],  refName)
                        // if(name){
                        schema.$ref = `#/definitions/${refName}`;
                        // }
                    }
            }
        break;
        case SyntaxKind.ArrayType: // 数组类型 ( 不支持数组 )
            schema.type = "array";
            if(properties && Object.keys(properties).length){
                schema.items = properToSchema(properties);
            }
        break;
        case SyntaxKind.TypeLiteral: // 匿名对象
            schema.type = "object";
            schema.properties = {};
            schema.required = [];
            for (const item of children) {
                schema.properties[item.name] = properToSchema(item);
                if(item.required) schema.required.push(item.name)
            }
        break;
        // 连接类型
        case SyntaxKind.UnionType:
            const list = Array.from(new Set(children.map((o) => o.flag)));
            if(list.length === 1){
                const childrenFlag = children[0].flag;
                switch(childrenFlag){
                    case TypeFlags.String:
                    case TypeFlags.StringLiteral:
                        schema.type = "string";
                        schema.enum = children.map((o) => getText(o.text, proper));
                    break;
                    case TypeFlags.Number:
                    case TypeFlags.NumberLiteral:
                        schema.type = "number";
                        schema.enum = children.map((o) => getText(o.text, proper));
                    break;
                    default:
                        return properToSchema(children[0]);
                }
            }else {
                // 组合类型
                schema.anyOf = children.map(properToSchema);
            }
        break;
        case SyntaxKind.BooleanKeyword:
            schema.type = "boolean";
        break;
        case SyntaxKind.StringKeyword:
        case SyntaxKind.SatisfiesKeyword:
            schema.type = "string";
        break;
        case SyntaxKind.NumberKeyword:
            schema.type = "number";
        break; 
        // 关联属性
        case SyntaxKind.LiteralType:
            if(text === "null"){
                schema.type = "null";
            }
        break;
        case SyntaxKind.Parameter:
            switch(flag){
                case TypeFlags.String:
                    schema.type = "string";
                break;
                case TypeFlags.Number:
                    schema.type = "number";
                break;
                case TypeFlags.Boolean:
                    schema.type = "boolean";
                break;
            }
        break;
        // 对象属性 (以下类型，不需要参与schema 计算)
        case SyntaxKind.PropertySignature:
        case SyntaxKind.SyntaxList: // 数据列表
        case SyntaxKind.Identifier: // 关联类型
    }
    setSchemaJsDocs(schema, jsDocs);
    return schema;
}


/**
 * @name 将typescript Interface 转为 schema
 */
export const InterfaceToSchema = (inter: InterfaceItem): JSONSchema => {
    const { jsDocs, name, children  } = inter;
    const schema: JSONSchema = {
        type: "object",
        title: name,
        properties: {},
        extraInfo: {
            jsDocs,
        },
        required: [],
    }
    for (const item of children) {
        schema.properties[item.name] = properToSchema(item);
        if(item.required) schema.required.push(item.name)
    }
    return schema;
}

/**
 * 接口转 schema 默认会将其他interface 引用在第一个schema 里面
 * @param bool 是否直接返回列表
 */
export const InterfaceListToSchema = (inters: InterfaceItem[]) => {
    const store = new TransformStore();
    inters.forEach((o) => {
        store.interNode[o.name] = o.children;
    })
    const list = inters.map((o) => InterfaceToSchema(o));
    const [schema, ...schemas ] = list;
    if(schemas.length){
        schema.definitions = {};
        for (const item of schemas) {
            if(item.title){
                item.title = item.title.endsWith('Props')? item.title.slice(0,-5) : item.title;
                schema.definitions[item.title] = item;
                delete item.title;
            }
        }
    }
    return schema as JSONSchema;
}