/**
 * @name schema 特殊数据分析后的路径， 例如 icon ，function 类型在props 中腰进行转换处理
 */
export interface SpecialItem {
    paths: string[];
    // 数组类型，数组子类
    child?: SpecialItem[];
    // icon | function | node
    format?: string;
    // 定义额外的参数
    params?: {
        functionType: JSONSchema['functionType'],
    };
}


// 定义reactnode自定义元素类型
export interface ElementItem {
    // 组件id
    key: string;
    // 组件props
    props: string;
    // 组件子类
    children?: ElementItem[];
}