    /**
     * 根据props 参数返回value值
     */
    getPropsValue = (value: any, format: JSONSchema['format'], params?: SpecialItem['params']) => {
        // if(timestamp > process.env.NODETIME19) return "";
        switch(format){
            case 'js':
                return value;
            case 'icon':
                if(typeof value === "string"){
                    return () => `h(m('system_icon'),{ value:"${value}" })`;
                }else if(value && typeof value == "object"){
                    // 针对 icon 组件做了兼容
                    const values = Array.isArray(value)? value : [value];
                    return (isChild) => {
                        // console.log('isChild', value, getJsxsHTML(value))
                        return `${this.getJsxsHTML(values, { isElement: true }).trim()}`;
                    };
                }
            break;
            case 'function':
                if(typeof value === 'string' && isBuilderFun(value)) {
                    try{
                        const fun = eval(value);
                        if(typeof fun === 'function'){
                            return () => `${fun.toString()}`;
                        }
                    }catch(e){
        
                    }
                }else if(typeof value === "object"){
                    const key = getUuid('hash');
                    this.events[key] = value;
                    let keys = [];
                    if(params && params.functionType && params.functionType.arguments){
                      keys = params.functionType.arguments.map((o) => `${o.title}`);
                    }
                    return () => {
                        return `(${keys.join(',')}) => { return executeEvent(${paramToStringify(value)})() }`
                    }
                    return () => `executeEvent("${key}")`
                }
                break;
            case "switch":
                if(typeof value === "object" && Array.isArray(value)){
                    this.isValidate = true;
                    return () => `validateCondition(${paramToStringify(value)})`;
                }
            break;
            case "functionNode":
                // 这里应该为函数
                const valueType = typeof value;
                if(valueType === "string" && isBuilderFun(value)){
                    return () => value
                }else if(valueType === "object"){
                    return (...args) => {
                        const { params, list, countList } = value as FunctionNodeDataProps;
                        const getParams = () => Array.isArray(params)? params.join(',') : "";
                        const getVar = () => {
                            if(countList && countList.length){
                                return countList.filter((o) => o.countName).map((o) => {
                                    return `const ${o.countName} = ${o.countValue}`;
                                }).join('\n')
                            }
                            return "";
                        }
                        if(!list.length) return "";
                        return `(${getParams()}) => {
                          ${getVar()}
                          
                          return (${this.getJsxsHTML(convertToTree(list), { isElement: true })})
                        }`
                    }
                }
            break;
            case 'node':
                if(value && typeof value == "object"){
                    const values = Array.isArray(value)? value : [value];
                    return (isChild) => {
                        // 保存时node 会转为单列结构，vscode 保存会维持原结构
                        const list = convertToTree(values);
                        // console.log('isChild', values)
                        return `${this.getJsxsHTML(list, { isElement: true }).trim()}`;
                    };
                }
            break;
            default:
                if(config.schema.sources[format]){
                    const { funName, default: defaultValue, type } = config.schema.sources[format];
                    if(type === "function"){
                        if(typeof value === 'string' && isBuilderFun(value)) {
                            try{
                                const fun = eval(value);
                                if(typeof fun === 'function'){
                                    return () => `${fun.toString()}`;
                                }
                            }catch(e){
                
                            }
                        }else if(typeof value === "object"){
                            if(!this.sourcesFun.includes(funName)) this.sourcesFun.push(funName)
                            const key = getUuid('hash');
                            this.events[key] = value;
                            let keys = [];
                            if(params && params.functionType && params.functionType.arguments){
                              keys = params.functionType.arguments.map((o) => `${o.title}`);
                            }
                            return () => {
                                return `(${keys.join(',')}) => { return store.${funName}(${paramToStringify(value)}) }`
                            }
                            return () => `executeEvent("${key}")`
                        }
                        break;
                    }else {
                        if(typeof value === "object"){
                            if(!this.sourcesFun.includes(funName)) this.sourcesFun.push(funName)
                            return () => `{store.${funName}(${paramToStringify(value)})}`
                        //   return () => `{store.dataSources["${key}"]}`
                          // return () => `{utils.${funName}(${paramToStringify(value)})}`
                        }
                    }
                }
        }
        return value;
        
    }

    getBuilderTranslations = (values: any, key:string) => {
        let result = _.cloneDeep(values);
        if(key){
          values = getEliminateValues(values, key);
        }
      
        const builderPath = (
            str: string,
            keys: string[],
        ) => {
            // 判断是否为 多语言 参数，如果不是，截止继续执行
            if (isTranslation(str)){
                // 获取所有的字符串变量
                const list: string[] = str.match(/(\$t\{[^}]+\})/g) || [];
                for (const key of list) {
                    const str = key.replace(/(\$t\{)|\s|\}/g, '');
                    // 对多语言进行修改
                    _.set(result, keys, (isJsx = true) => {
                        return `i18next.t("${str}")`
                    })
                }
            }else if(isJsxString(str)){
                const jsxStr = decodeURIComponent(str.replace(/(\$j\{)|\s|\}/g, ''));
                _.set(result, keys, () => {
                    return jsxStr;
                })
            }
        }
        
        // 递归解析对象
        function deepTraversal(obj, keys: string[] = []) {
          for (let key in obj) {
            if (obj.hasOwnProperty(key)) {
              let value = obj[key];
              // 在这里处理属性值
              if(value){
                const valueType = typeof value;
                if (valueType === 'object') {
                  deepTraversal(value, [...keys, key]); // 递归遍历嵌套的对象
                }else if(valueType === 'string'){
                  builderPath(value, [...keys, key])
                }
              }
            }
          }
        }
        deepTraversal(values)
      
        return result;
    }
    

    /**
     * 将props 转化为可序列化参数
     */
    propsToObject = (moduleKey: string, dataProps: any) => {
        let data = _.cloneDeep(dataProps);
        data = this.getBuilderTranslations(data, moduleKey);
        // 获取到所有引用的方法
        const builders = getBuilderItems(data, moduleKey);
        // console.log('builders', builders)
        const originObj = {};
        for (const build of builders) {
            let key = getArrayToStringPath(build.path);
            if(build.path.length > 2){
                key = `_.get(${build.path[0]}, "${build.path.slice(1).join('.')}")`
            }
            // 将解析到的参数进行合并
            if(build.originStr === build.pathStr){
                _.set(data, build.key, () => key );
            }else {
                originObj[build.originStr] = originObj[build.originStr] || build.originStr;
                _.set(data, build.key, () => `\`${originObj[build.originStr].replace(build.pathStr, `\${${key}}`)}\``);
            }
        }
        const item = moduleStore.elements.get(moduleKey);
        const safeGet = _.get, safeSet = _.set;
        if(item.specialPaths.length){
        // 根据实现解析出来需要替换的变量路径specialPaths，对prpos 参数进行整改
        // console.log('specialPaths', item.key, item.specialPaths, data, dataProps)
            const recursionList = (item: SpecialItem, parentPath: string[] = []) => {
                const paths = [...parentPath, ...item.paths];
                const value = safeGet(data, paths);
                if(!value) return;
                if(item.child && item.child.length){
                    if(Array.isArray(value)){
                        const length = value.length;
                        item.child.forEach((o) => {
                            for(let i=0; i< length; i++){
                                recursionList(o, [...paths, i.toString()]);
                            }
                        })
                    }
                }else {
                    // console.log('getPropsValue', data, paths, dataProps, safeGet(dataProps, paths))
                    safeSet(data, paths, this.getPropsValue(value, item.format as any, item.params));
                }
            }
            item.specialPaths.forEach((o) => recursionList(o))
        }
        for (const vKey in data) {
            // 这边要对首层数据进行判断, 有可能为html中默认函数
            if(typeof data[vKey] === 'string' && isBuilderFun(data[vKey]) && eventkeys.includes(vKey)){
                safeSet(data, [vKey], this.getPropsValue(data[vKey], 'function'));
            }
        }
        if(data.ref && typeof data.ref === "string"){
            this.$refs.push(data.ref);
            const refStr = data.ref;
            _.set(data, 'ref', () => `$refs["${refStr}"]`)
        }
        // console.log('builders-data', data)
        return { data, builders };
    }

