    /**
     * 创建useEffect 函数
     */
    getEffectsText = (page: pageDataProps['page']) => {
        const { useEffects } = page
        if(Array.isArray(useEffects)){
            return useEffects.filter((o) => {
                return o.value;
            }).map((o) => {
                const fun = eval(o.value);
                if(typeof fun === 'function'){
                  const funStr = fun.toString();
                  const vars = (o.vars || []).map((str) => {
                    const key = getBuilderItems({ a: str })[0].path.join('.');
                    return `${key}`;
                  })
                  return `useEffect(${funStr}, [${vars.join(',')}]);\n`
                }
                return "";
            }).join("\n");
        }

        return "";
    }

    
