import React, { memo, useEffect, useMemo, useState } from 'react';
import type { ListItem, pageProps } from 'src/components/CustomPage/interface';
import moduleStore from 'src/store/moduleStore';
import PageContent from './Content';
import { convertToTree } from 'src/utils';
import Store from 'src/components/container/store';

interface NodeElementProps {
    list: ListItem[];
    // 页面参数
    store: Store;
}

/**
 * 页面内容区域 taro-container
 * @param width 750
 * @param height 900
 */
const NodeElement = memo(({ list: elementList, store }: NodeElementProps) => {

    const list = useMemo(() => {
        return elementList;
        // return elementList.map((o) => {
        //     return {
        //         ...o,
        //         props: getTranslations(store, o.props)
        //     }
        // })
    },[elementList])

    const [nodeList, setNodeList] = useState<any[]>(() => {
        // 判断当前组件是否已经全部注册过了，如果是，则不再异步加载
        if(list.every((o) => moduleStore.elements.has(o.key))){
            return convertToTree(list, 'id', 'parentId');
        }
        return [];
    });

    useEffect(() => {
        if(nodeList.length) return; // 列表已经存在跳过列表校验
        if(list.length){
            moduleStore.syncModuleIds(list.map((o) => o.key)).then((res) => {
                setNodeList(convertToTree(list, 'id', 'parentId'));
            })
        }else {
            setNodeList([]);
        }
    },[list])

    // console.log('nodeList', nodeList, list, elementList)
  
    if(nodeList.length) return <PageContent list={nodeList} store={store} />

    return null;
});

export default NodeElement;
  