/**
 * 将JSON Schema 转为单列数据
 */
 export interface JSONSchemaItemProps {
    id: string;
    type: JSONSchema['type'];
    // json 路径
    path: string[];
    // schema 路径
    schemaPath: string[];
    // schema 父级路径
    anyOf?: JSONSchemaItemProps[];
    // parentSchemaPath?: JSONSchema;
    key?: string;
    children?: JSONSchemaItemProps[];
    _store: JSONSchema;
  }
  